  ('ch2_KAL-011', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की खोज/पहचान के इतिहास में 1952 में किसका नाम आता है?', 'श्री अमलानंद घोष ने 1952 में अपने exploration के दौरान इस स्थल को प्रमुखता से पहचाना (first highlighted)।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-011 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b873faccf173200656c1dd29ddc5cbe1830c7b856da365c11ec7975719936a14', NULL),
  ('ch2_KAL-012', 'catalog.rajasthan_history_ancient_history_kalibangan', 'L. P. Tessitori ने कालीबंगा क्षेत्र का सर्वेक्षण किस अवधि में किया?', '1916–1919 के अपने राजपूताना सर्वेक्षण के दौरान; उन्होंने 1917 और 1918 में स्थल का दौरा किया।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-012 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd4f3f9fad871c97db38582691dc021ca83ad117cd051a6f7d2552100fe8c127b', NULL),
