  ('ch2_KAL-014', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर कालीबंगा का सबसे पुराना दर्ज लिखित उल्लेख किससे जोड़ता है?', 'James Tod से; गज़ेटियर इसे संभावित earliest recorded mention कहता है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-014 — S4 — printed p. 36; wording is qualified — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6e0534709b265a65de7b92196650d7350483a9ae6f901161f092fe61cf11a0c7', NULL),
  ('ch2_KAL-015', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा का व्यवस्थित उत्खनन किस संस्था के अधीन हुआ?', 'भारतीय पुरातत्व सर्वेक्षण (Archaeological Survey of India — ASI) के अधीन।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-015 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'bed54f7930540a2d3fb0deed831e6c99009d5f2c31a4849728eafc2a2c22ddc9', NULL),
