  ('ch2_KAL-018', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के उत्खनन से जुड़े प्रमुख पुरातत्वविद् कौन थे?', 'प्रो. B. B. Lal, B. K. Thapar और J. P. Joshi।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-018 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8e2e7123a31cbe1165e055dbe99263eb4268b1fee37c582551e7535ac816285d', NULL),
  ('ch2_KAL-019', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा स्थल पर कितने मुख्य numbered mounds (KLB-1, KLB-2, KLB-3) का वर्णन है?', 'तीन। इनके अतिरिक्त cemetery mound KLB-8 का भी उल्लेख है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-019 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4ad4e3c68f1f67fa3724640ff586487ec75ce1c117eca1ed9a66693510d6fe9b', NULL),
