  ('ch2_KAL-141', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के तीसरे प्रकार के शवाधान-गड्ढे में मिट्टी के बर्तनों के साथ कौन-सी छोटी वस्तुएँ रखे जाने का उल्लेख है?', 'चूड़ियाँ, मनके, हड्डी के नुकीले औज़ार और ताँबे की वस्तुएँ आदि।', 'hi', 'https://www.asijodhpurcircle.in/museum', 'KAL-141 — S7 — “Burial Site (KLB-8)” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6f32c023da907dfdda1f7723542742e7824ccf8f7245bbaebb69d7b19cc87a4e', NULL),
  ('ch2_KAL-142', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के कब्रिस्तान-टीले KLB-8 को भारतीय पुरातत्व सर्वेक्षण संग्रहालय का पृष्ठ किस मुख्य पुरातात्त्विक महत्त्व से जोड़ता है?', 'यह स्थल की शवाधान पद्धतियों और अंत्येष्टि-रीतियों का प्रमाण देता है।', 'hi', 'https://www.asijodhpurcircle.in/museum', 'KAL-142 — S7 — “Burial Site (KLB-8)” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e93dbdc97321d12bda05e337efaeae4e368bc1484f352279d288ce5bb8fbae9b', NULL),
