  ('ch2_KAL-146', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण के लेखक ने किस प्रकार के पत्थर के फलकों को हड़प्पा सभ्यता का विशिष्ट सांस्कृतिक लक्षण कहा है?', 'समानांतर किनारों वाले पत्थर के फलकों को।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-146 — S6 — Ch. 11, printed pp. 723–727 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '10dd9ba4cb75148011f9baf9aa5869b45a619cfff948c5e2e37e1d42312842b6', NULL),
  ('ch2_KAL-147', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के हड़प्पाई स्तरों से पत्थर का कच्चा माल और औज़ार किन रूपों में मिले?', 'चर्ट के पिंड और कंकड़, पत्थर के निकले हुए टुकड़े, केंद्रक तथा तैयार औज़ार।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-147 — S6 — Ch. 11, printed pp. 727–730 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '624d2273456255a97270fc5eba358d3c0373e50074343cfa3c002b6f3c61d341', NULL),
  ('ch2_KAL-148', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण के भाग दो के अनुसार कालीबंगा के पत्थर के औज़ार-संग्रह में कौन-सी वस्तु अन्य औज़ारों से अधिक संख्या में थी?', 'पत्थर के निकले हुए टुकड़े।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-148 — S6 — Ch. 11, printed pp. 727–730 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a2f8cf13d730f50233e45e16f78f1766f72640af428cc97f70974f9c182b2963', NULL),
  ('ch2_KAL-149', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा में कम संख्या में दर्ज विशिष्ट पत्थर के औज़ारों के प्रकार कौन-से थे?', 'काँटेदार आधार वाली नोकें, कंधेदार नोकें, छेदक, खाँचेदार नोकें, तीरों के अग्रभाग, उत्कीर्णक, दाँतेदार फलकीय औज़ार और खाँचेदार फलकीय औज़ार।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-149 — S6 — Ch. 11, printed pp. 727–730 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '9a365550df5c1840715ac9d27d1c05717671e6f90a5e14a3f185473a1a6ba0e2', NULL),
  ('ch2_KAL-150', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा में पत्थर के फलकीय औज़ार बनाने के लिए किन दो खंडन तकनीकों का उल्लेख है?', 'दबाव द्वारा खंडन तथा आघात द्वारा खंडन।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-150 — S6 — Ch. 11, printed pp. 730–732 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b2d733cc3bfe2f343c94a7961638fb061939928c8eedb94a52c0475de7ea000f', NULL),
  ('ch2_KAL-151', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण के लेखक के अनुसार बड़ी संख्या में फलकीय औज़ार बनाने में किस प्रकार के केंद्रक का उपयोग हुआ?', 'प्रिज्माकार केंद्रक का।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-151 — S6 — Ch. 11, printed pp. 730–732 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '765a1cb77a1ba5a6cceae75a40fc0f61966da876a3e97871e9ed8f724179dbe6', NULL),
  ('ch2_KAL-152', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण के भाग दो में तेज़ी से पत्थर के फलक बनाने की तकनीक का क्या नाम दिया गया है?', 'शिखरित मार्गदर्शक धार तकनीक।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-152 — S6 — Ch. 11, printed pp. 730–732 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '54426a49e42bc6dbfb7f3cfab92974ee61bb577d14d5631f4a5a3513c90e52cd', NULL),
  ('ch2_KAL-153', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण के लेखक ने काँटेदार आधार और कंधे वाली पत्थर की नोकों का संभावित उपयोग क्या बताया है?', 'लकड़ी में छेद करने अथवा बने हुए छेद को चौड़ा करने के लिए; यह लेखक की कार्य-व्याख्या है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-153 — S6 — Ch. 11, printed pp. 727–730 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '5f7fbbfc9c009d53a7fce6904f7210f50cd736eaa87405c3424341784718dcb6', NULL),
  ('ch2_KAL-154', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण के लेखक ने समानांतर किनारों वाले पत्थर के फलक के छोटे टुकड़ों को किस संभावित कृषि-उपकरण से जोड़ा है?', 'लकड़ी की दरांती में डामर से तिरछे जमाए गए फलकीय टुकड़ों के रूप में, जिनसे अनाज की फसल काटी जाती थी; यह उत्खनन-सामग्री पर आधारित व्याख्या है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-154 — S6 — Ch. 11, printed pp. 727–732 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd5b10ad32343af33eaf60eefa2cfa442023738b78067021127ceace5666e2371', NULL),
  ('ch2_KAL-155', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के पत्थर के औज़ारों में प्रयुक्त चर्ट के कौन-से रंग दर्ज हैं?', 'भूरा और धूसर चर्ट।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-155 — S6 — Ch. 11, printed pp. 727–730 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4d757ea5ac1138d0f31da39ae522ae0b7cdfc1467bffec6bf3b1cab98f153395', NULL),
  ('ch2_KAL-156', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण के भाग दो के अनुसार कालीबंगा के हड़प्पाई स्तरों से हाथीदाँत और हड्डी की कितनी वस्तुएँ अथवा संबंधित सामग्री दर्ज हुई?', 'कुल 392 वस्तुएँ; इनमें छोटे टुकड़े, कच्चे माल के टुकड़े और निर्माण-अवशेष भी शामिल हैं।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-156 — S6 — Ch. 13 “Ivory and Bone Objects”, printed pp. 809–811 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'dff3078a77b884b6ef47f2a878041f05dae4707e39723e7582dfd11a32398d5d', NULL),
  ('ch2_KAL-157', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा में हाथीदाँत और हड्डी की वस्तुओं के स्थानीय निर्माण का संकेत किन साक्ष्यों से मिलता है?', 'कच्चे हाथीदाँत और हड्डी के टुकड़े तथा अर्ध-निर्मित वस्तुएँ मिलने से; रिपोर्ट इसे स्थानीय निर्माण का संकेत मानती है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-157 — S6 — Ch. 13, printed pp. 809–811 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e75d2482d9f32496d3069d22ac7f2ac1cd9ddd44a6e17ef091d949d811b96479', NULL),
  ('ch2_KAL-158', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण के भाग दो में कालीबंगा की हाथीदाँत और हड्डी की वस्तुओं की कौन-सी श्रेणियाँ सूचीबद्ध हैं?', 'कंघियाँ, कंधास्थियाँ, लेखनियाँ, तीरों के अग्रभाग, सुइयाँ, सुरमा लगाने की सलाइयाँ, शंक्वाकार वस्तुएँ, हाथीदाँत के टुकड़े तथा पशुओं के सींग।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-158 — S6 — Ch. 13, printed pp. 809–811 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '61013d131048b62ff548dcbe3744f8000eccff4c5aee270e082136ce90fd9ebe', NULL),
  ('ch2_KAL-159', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा से हाथीदाँत की कितनी कंघियाँ मिलने का उल्लेख भारतीय पुरातत्व सर्वेक्षण की रिपोर्ट में है?', 'चार; इनमें से तीन अपेक्षाकृत कम क्षतिग्रस्त थीं और उनका वर्णन तथा चित्रांकन किया गया।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-159 — S6 — Ch. 13, “Combs”, printed pp. 811–815 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '892b71f546308e334a639602019ce2a748a2a5b29420c3a043f490ed024131d8', NULL),
  ('ch2_KAL-160', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण की रिपोर्ट के अनुसार कालीबंगा में हाथीदाँत का सामान्य उपयोग किन वस्तुओं के निर्माण में बताया गया है?', 'हाथीदाँत की वस्तुएँ कम थीं और इसका सामान्य उपयोग कंघियाँ बनाने में बताया गया है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-160 — S6 — Ch. 13, printed pp. 809–815 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1e0737820b5861578d6fbd8258f8709441e562e07d44dce7bda13695a5ee81e6', NULL),
  ('ch2_KAL-161', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा के कितने अभिलिखित मृद्भांड-खंडों पर चिह्नों के एक-दूसरे पर चढ़ने का प्रमाण बताया?', 'दो मृद्भांड-खंडों पर; लाल ने इनके चिह्नों के अतिव्यापन से लेखन-दिशा का क्रम समझाया।', 'hi', 'https://ignca.gov.in/Asi_data/57533.pdf', 'KAL-161 — S12 — “Some Aspects of the Archaeological Evidence Relating to the Indus Script”, printed pp. 22–23 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '030cd79bec1bd3743bb46ceec6e2d46c1c3083ff073fc0397e5c08703bdb9a6d', NULL),
  ('ch2_KAL-162', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के 1974 के अध्ययन में हड़प्पाई लिपि की सामान्य लेखन-दिशा क्या बताई गई?', 'दाएँ से बाएँ; यह निष्कर्ष कालीबंगा के दो अभिलिखित मृद्भांड-खंडों पर चिह्नों के अतिव्यापन पर आधारित था।', 'hi', 'https://ignca.gov.in/Asi_data/57533.pdf', 'KAL-162 — S12 — printed p. 22 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0ba6bb819e164a8610cd171ab7aab6795d273c3411a28d6e92ab8c5ad3be6c9d', NULL),
  ('ch2_KAL-163', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के अनुसार हड़प्पाई लिपि की दूसरी पंक्ति कभी-कभी किस लेखन-शैली में लिखी जाती थी?', 'बुस्ट्रोफेडन शैली में; लेखक ने यह भी कहा कि ऐसा हर बार आवश्यक नहीं था।', 'hi', 'https://ignca.gov.in/Asi_data/57533.pdf', 'KAL-163 — S12 — printed p. 22 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4aaef997c5bfe2fba0f28decd2cc62b8e6eec1542c0391fdfa8e69a1323c0d87', NULL),
  ('ch2_KAL-164', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा के दुर्ग क्षेत्र में एक ही लेख वाले मिट्टी के कितने मुहर-चिह्नों का उल्लेख किया?', 'सात मुहर-चिह्नों का।', 'hi', 'https://ignca.gov.in/Asi_data/57533.pdf', 'KAL-164 — S12 — printed p. 23, “Some Observations on the Use of the Indus Seals” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8afac2c78f70d1f1104de897ad032c5876dfb7ad2ac71868beb0d3fe12c6ec10', NULL),
  ('ch2_KAL-165', 'catalog.rajasthan_history_ancient_history_kalibangan', 'लाल के अनुसार कालीबंगा के समान लेख वाले सात मुहर-चिह्नों का भौतिक रूप कैसा था?', 'पकी हुई मिट्टी की लंबी पट्टियों के रूप में; उनके पीछे पैकिंग-सामग्री की छाप नहीं थी।', 'hi', 'https://ignca.gov.in/Asi_data/57533.pdf', 'KAL-165 — S12 — printed p. 23 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ae6ec220f4daf8550655bd82039b13758fb26dc09e1ad06b8f7f0e3348c8f587', NULL),
  ('ch2_KAL-166', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने सिंधु सभ्यता की मुहरों का प्राथमिक उपयोग क्या माना?', 'वस्तुओं अथवा पैकेजों पर छाप लगाने के लिए; उनके अनुसार बनी हुई उभरी छाप पढ़ने के लिए थी।', 'hi', 'https://ignca.gov.in/Asi_data/57533.pdf', 'KAL-166 — S12 — printed p. 23 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'f1d02ee9dc8f188b70ea88b597dd4800f0cfa93f0985dde9092031eabeb0168a', NULL),
  ('ch2_KAL-167', 'catalog.rajasthan_history_ancient_history_kalibangan', 'लाल के अनुसार कालीबंगा से मिले अभिलेख किन प्रकार की वस्तुओं पर दर्ज थे?', 'मुहरों, मुहर-चिह्नों, ताँबे और काँसे की वस्तुओं, मृद्भांडों तथा हाथीदाँत की छड़ियों आदि पर।', 'hi', 'https://ignca.gov.in/Asi_data/57533.pdf', 'KAL-167 — S12 — printed p. 23 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '107195fa0786fbc9a2122f52c364bfe1f39b373e740f893f63af915b9824d888', NULL),
  ('ch2_KAL-168', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा के खुरचकर बनाए गए चिह्नों में वी-आकार के चिह्न की संभावित आकृति किस वस्तु से जोड़ी?', 'लंबे और संकरे आधार वाले फूलदान अथवा मटके जैसी आकृति से; यह लाल का 1974 का व्याख्यात्मक प्रस्ताव है, लिपि का प्रमाणित पाठोद्धार नहीं।', 'hi', 'https://ignca.gov.in/Asi_data/57533.pdf', 'KAL-168 — S12 — printed p. 23 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6016ef8fd280e44056cb132c8b8bf7a73dc9c5c4fc08012bfc03b5839aee0738', NULL),
  ('ch2_KAL-169', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण के कालीबंगा प्राणी-अस्थि अध्ययन में कितने खंडित नमूनों की पहचान की गई?', '5,230 खंडित नमूनों की।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2021-22.pdf', 'KAL-169 — S10 — Annual Report 2021–22, project “Zooarchaeology of Faunal remains of Kalibangan”, printed pp. 34–35 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '00555b15df9fd6f68faf0e375728625cee86d3bd10212b22edbdf9e1997c8d91', NULL),
  ('ch2_KAL-170', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण के कालीबंगा प्राणी-अस्थि अध्ययन में पहचाने गए अवशेष कितनी जातियों, वंशों, कुलों, गणों और वर्गों से संबंधित थे?', '36 जातियाँ, 30 वंश, 18 कुल, 11 गण और 5 वर्ग।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2021-22.pdf', 'KAL-170 — S10 — Annual Report 2021–22, printed pp. 34–35 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '5d5171743342cec653031a89e8d35920b76f8f9fa2c48f152d137f88b6e40875', NULL),
  ('ch2_KAL-171', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण के अनुसार कालीबंगा के प्राणी-अवशेषों में अधिकांश हड्डियाँ किन पालतू पशुओं और पक्षियों की थीं?', 'पालतू गाय-बैल, भैंस, भेड़, बकरी, ऊँट और मुर्गी आदि की।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2021-22.pdf', 'KAL-171 — S10 — Annual Report 2021–22, printed p. 35 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '42946fbd0ba02f804164a9cfffd364155e60e0af823f2665e0faab10b78d9891', NULL),
  ('ch2_KAL-172', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण की व्याख्या के अनुसार कालीबंगा के अधिकांश पशु-अवशेष किस प्रकार के पुरातात्त्विक संदर्भ से आए थे?', 'प्राचीन निवासियों के भोजन-संबंधी अपशिष्ट से।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2021-22.pdf', 'KAL-172 — S10 — Annual Report 2021–22, printed p. 35 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '33704816c661b30871640ea7258cb6a658079fb33ecf555b20641e3fea9840f2', NULL),
  ('ch2_KAL-173', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण के अनुसार कालीबंगा की पशु-हड्डियों पर मानव गतिविधि के कौन-से निशान मिले?', 'जलने, काटने और टुकड़े करने के निशान।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2021-22.pdf', 'KAL-173 — S10 — Annual Report 2021–22, printed p. 35 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c32bf91425e1444eb3fb8e915ba815760b5c0281a44cf6ec18b97d614f3f7f6e', NULL),
  ('ch2_KAL-174', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण के प्राणी-अस्थि अध्ययन के अनुसार कालीबंगा में किन प्रमुख जंगली पशुओं के अवशेष भी मिले?', 'हिरण की विभिन्न प्रजातियों, गैंडे और गौर आदि के; साथ में कुछ कछुए तथा मृदुकाय जीवों की प्रजातियाँ भी दर्ज हुईं।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2021-22.pdf', 'KAL-174 — S10 — Annual Report 2021–22, printed p. 35 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6f1a04200a784092f6694d8528a8a4ab82634db4211cf30810255e3e752826cc', NULL),
  ('ch2_KAL-175', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय पुरातत्व सर्वेक्षण की 1974–75 की समीक्षा में कालीबंगा के पकी मिट्टी के टिक्कों और पैई में मिले पौध-अवशेष मुख्यतः किन फसलों के बताए गए?', 'जौ तथा कुछ मामलों में गेहूँ के।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201974-75%20A%20Review.pdf', 'KAL-175 — S11 — Section VI “Palaeobotanical and Pollen Analytical Investigations”, printed p. 79 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '7a72e4031b9d5fad4c9b7a39c4f5ceeb10e64492f000b2743593613b480cc188', NULL),
  ('ch2_KAL-176', 'catalog.rajasthan_history_ancient_history_kalibangan', 'विष्णु-मित्रे और आर. सावित्री ने कालीबंगा में पहले बताए गए धान-अवशेषों की पहचान पर क्या आपत्ति उठाई?', 'उन्होंने कहा कि टिक्कों और पैई में धान की बाहरी कोशिका-परत तथा धान का विशिष्ट चौखानेदार नमूना नहीं मिला; इसलिए पहले की धान-पहचान ठोस आधार पर नहीं थी।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201974-75%20A%20Review.pdf', 'KAL-176 — S11 — printed p. 79; authors cite *Palaeobotanist* 22(2), 1975, pp. 124–126 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c3c8fe8ffb441cc18961d6540cb42852348ea1f575c90f48b142add35e0d291e', NULL),
  ('ch2_KAL-177', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के धान-साक्ष्य के संबंध में टिप्पणियों में स्रोत-विरोधाभास क्यों दर्ज किया गया है?', 'भारतीय पुरातत्व सर्वेक्षण, जोधपुर मंडल का संग्रहालय-पृष्ठ धान का उल्लेख करता है, जबकि 1974–75 की सर्वेक्षण-समीक्षा में विष्णु-मित्रे और सावित्री ने उन्हीं पकी मिट्टी के टिक्कों तथा पैई के कथित धान-अवशेषों को जौ और कुछ मामलों में गेहूँ बताया; इसे अनसुलझे स्रोत-विरोध के रूप में रखा गया है।', 'hi', 'https://www.asijodhpurcircle.in/museum', 'KAL-177 — S7 — “The Early Harappan Period”; S11 — printed p. 79 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '91c201bdf31e56df4208da257e348a2d43d0442cb7dad80e1837f435102b2c20', NULL),
  ('ch2_KAL-178', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण का प्राणी-अस्थि अध्ययन कालीबंगा के पशु-अवशेषों को किन सांस्कृतिक चरणों से जोड़ता है?', 'पूर्व-हड़प्पा और हड़प्पा—दोनों चरणों से।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2021-22.pdf', 'KAL-178 — S10 — Annual Report 2021–22, printed p. 35 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '25c6b00ec64a9a3c6784fe3b4237efb6469fac33e5015f5835b5238e61d90208', NULL),
  ('ch2_KAL-179', 'catalog.rajasthan_history_ancient_history_kalibangan', 'सिंधु मुहरों और अभिलेखों के संकलन में कालीबंगा की वस्तुएँ किस संदर्भ-क्रम में सूचीबद्ध हैं?', 'K-1 से K-122 तक; संकलन में कालीबंगा का चित्रित सूची-विवरण मुद्रित पृष्ठ 298–326 पर है। यह सूची-संदर्भ क्रम है, 122 मुहरों की कुल संख्या नहीं।', 'hi', 'https://ignca.gov.in/Asi_data/76884.pdf', 'KAL-179 — S13 — Vol. 1 “Collections in India”, printed pp. 298–326 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'cefb2189fc983d5f859ab8283a9fedabde536cc47fc4d69c35c8b42a39eb64ad', NULL),
  ('ch2_KAL-180', 'catalog.rajasthan_history_ancient_history_kalibangan', 'क्या कालीबंगा संकलन-ग्रंथ की के-श्रृंखला की प्रत्येक प्रविष्टि को मुहर कहना सही होगा?', 'नहीं; K-122 जैसी प्रविष्टि को ‘विविध—ताँबे की वस्तुएँ’ श्रेणी में रखा गया है। के-श्रृंखला में केवल एक ही प्रकार की वस्तु नहीं है।', 'hi', 'https://ignca.gov.in/Asi_data/76884.pdf', 'KAL-180 — S13 — K-122, printed p. 326 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd2d0f8a03b2cc0d7441df95a71264fdf914bf67fd34070132d579e4992a11fc4', NULL),
  ('ch2_KAL-181', 'catalog.rajasthan_history_ancient_history_kalibangan', '‘सिंधु मुहरों और अभिलेखों के संकलन’ में K-122 को किस श्रेणी में रखा गया है?', '‘विविध—ताँबे की वस्तुएँ’ श्रेणी में; पृष्ठ पर K-122 A और K-122 B के चित्र भी दिए गए हैं।', 'hi', 'https://ignca.gov.in/Asi_data/76884.pdf', 'KAL-181 — S13 — printed p. 326 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'dcd2c7435b64a665c767f3b46b7685d2cdd007b5cdd69de248f8d3e55eee0ca1', NULL),
  ('ch2_KAL-182', 'catalog.rajasthan_history_ancient_history_kalibangan', 'इरावतम महादेवन ने कालीबंगा की विशिष्ट मुहर संख्या 8011 को किस पदार्थ का बताया है?', 'गुलाबी टेराकोटा अर्थात पकी मिट्टी का; इसके पीछे उभरा हुआ आधार-उभार है, जो इसे छाप-मुहर के रूप में पहचानने में सहायक है।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-182 — S14 — Introduction, Note 7, printed p. 25 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '72aef99196af5d950b1b36d65f4b6c1ea7d0e2519a5834fd343330065c9c8e05', NULL),
  ('ch2_KAL-183', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन के अनुसार कालीबंगा की मुहर 8011 पर कौन-से दो प्रमुख चिह्न उभरे हुए बने हैं?', 'दो पंक्तियों का लेख और बाईं ओर देखता हुआ गैंडे का प्रतीक; मूल वस्तु पर दोनों उभरे हुए हैं।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-183 — S14 — Introduction, Note 7, printed p. 25 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e2d8a0c2573e00c3b847050fe9b8280ba227a73b7d407ee36dc91b8fa2f03be4', NULL),
  ('ch2_KAL-184', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन ने मुहर 8011 को सिंधु मुहरों की किस विशिष्ट उपश्रेणी में रखा?', '‘उभरी मुहर’ नामक अलग उपश्रेणी में; उनके अनुसार साँचे से बनी मुहर की छाप धँसी हुई होगी।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-184 — S14 — Introduction, Note 7; Fig. 27, Plate II, printed p. 803 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b0f31040cc2049a3685f29f8fa2a7c0f9bd23fe18c1ccfc8d70c9545a96ba66f', NULL),
  ('ch2_KAL-185', 'catalog.rajasthan_history_ancient_history_kalibangan', 'इरावतम महादेवन ने 1976 में सिंधु लिपि की चिह्न-सूची और चिह्न-रूपांतरों में संशोधन क्यों किया?', 'लोथल और कालीबंगा से मिले अप्रकाशित अभिलेख उपलब्ध होने के बाद चिह्न-सूची को अद्यतन किया गया।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-185 — S14 — Introduction, §§2.2–2.3 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '37d050f70816958d5b33a869d5a4a2c4a422764c0c10f51183db5dd83da35807', NULL),
  ('ch2_KAL-186', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन ने अपने सिंधु लिपि-संकलन में किसी लेख को शामिल करने के लिए किस प्रकार का स्रोत-मानदंड अपनाया?', 'प्रत्येक लेख को मूल वस्तु से सीधे उतारा या उसकी ढलाई, छायाचित्र अथवा छाप से लिया; मूल स्रोत उपलब्ध न होने पर उसे संकलन से बाहर रखना पसंद किया।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-186 — S14 — Introduction, §3.6 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0fa14376ade259a3c198635360751344de72d6e45bbe761fcb20ed638148489e', NULL),
  ('ch2_KAL-187', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण की 2018–19 की वार्षिक रिपोर्ट में कालीबंगा के जीव-अवशेष अध्ययन ने प्रारम्भ में कितनी प्रजातियों की पहचान दर्ज की?', '11 स्तनधारी, 1 पक्षी और 2 सरीसृप प्रजातियाँ—कुल 14 प्रजातियाँ। उस रिपोर्ट में परियोजना जारी थी।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2020-21.pdf', 'KAL-187 — S15 — Annual Report 2018–19, project 21, printed p. 039 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a7ddfa70dbd95d377293c5b3bdf262c39f7255b4ebf3223a04c4f83f52a6d9f1', NULL),
  ('ch2_KAL-188', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण की 2020–21 की वार्षिक रिपोर्ट में कालीबंगा से कितने जीव-अवशेष नमूने और कितनी प्रजातियाँ दर्ज थीं?', '1,075 नमूने, 19 प्रजातियाँ, 9 कुल और 6 गण; उस रिपोर्ट में परियोजना जारी थी।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2020-21.pdf', 'KAL-188 — S15 — Annual Report 2020–21, project 19, printed p. 031 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '444bfb5ebaf849d6e2d87e250cccacf0e01a62af0bffad2f0e9f3f11a13da840', NULL),
  ('ch2_KAL-189', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन के ‘सिंधु लिपि’ संकलन में कालीबंगा संदर्भ 8123 किस वस्तु के लिए दिया गया है?', 'मिट्टी के ढेले पर सुरक्षित मुहर-छाप वाली मिट्टी की मुद्रा के लिए; इसे मूल वस्तु एएसआई 68.1.70 से उतारा गया था।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-189 — S14 — Introduction §16.2 “Notes on the additional texts”, printed p. 24 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '815ac0e0fa8d8a9b0fc79cb161da4d6ae9e7687e9e88d8f73c0a38d2965bac14', NULL),
  ('ch2_KAL-190', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन के संकलन में कालीबंगा संदर्भ 8222 किस प्रकार की वस्तु है?', 'एक-दूसरे को काटती हुई खुदाई-रेखाओं वाला अभिलेखित मृद्भांड-खंड; इसे ‘पुरातत्त्व’ 7 (1974), पट्ट VI-A से जोड़ा गया है।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-190 — S14 — §16.2, printed p. 24 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a32d712ee79ac1a65d394c7078f358b0d2f4b4f46dcdc11a364f9ad87474d930', NULL),
  ('ch2_KAL-191', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन के संकलन में कालीबंगा संदर्भ 8401 का आकार और अभिलेखीय विशेषता क्या है?', 'अंडाकार टेराकोटा वस्तु, जिसकी दोनों सपाट सतहों पर एक-एक बड़ा चिह्न खुदा हुआ है।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-191 — S14 — §16.2, printed p. 24 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0575758803939c7ad6409d0b490855c8456f46b44a90a850def44d947e382e80', NULL),
  ('ch2_KAL-192', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा के प्रथम सांस्कृतिक काल को ‘पूर्व-हड़प्पा’ कहने के साथ कौन-सा वैकल्पिक सांस्कृतिक अर्थ भी सुझाया?', 'इसे सम्भवतः आद्य-हड़प्पा या प्रारम्भिक हड़प्पा चरण मानने का प्रस्ताव रखा; यह उनका सांस्कृतिक वर्गीकरण संबंधी सुझाव है।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-192 — S16 — “Kalibangan and the Indus Civilization”, printed p. 66 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2c400ab8d13c41e88ffe156c7ba22dd63b0c1646c19a443a119df25e0d632739', NULL),
  ('ch2_KAL-193', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के अनुसार कालीबंगा स्थल की कुल परिधि लगभग कितनी थी?', 'लगभग 1.5 से 2 किलोमीटर; उनके अध्याय में टीले की औसत ऊँचाई आसपास की भूमि से लगभग 10 मीटर बताई गई है।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-193 — S16 — printed p. 66 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0ae3137e191157ec136ce01e4c6feb046eceac642fd04de9214170cc1848bef3', NULL),
  ('ch2_KAL-194', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के विवरण में प्रथम सांस्कृतिक काल के परकोटे की पश्चिमी और पूर्वी दीवारों की लम्बाई कितनी थी?', 'पश्चिमी दीवार लगभग 240 मीटर और पूर्वी दीवार लगभग 250 मीटर।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-194 — S16 — printed p. 67 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c921e0a3bf86cf8aa1715420bf840224e6e23c4a8a95dc18251ed95e82e8d131', NULL),
  ('ch2_KAL-195', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के अनुसार प्रथम सांस्कृतिक काल के परकोटे की दक्षिणी दीवार की लम्बाई कितनी थी?', 'लगभग 170 मीटर; उत्तर की दीवार सीधी रेखा में न होकर मोड़ लेकर चलती थी।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-195 — S16 — printed p. 67 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ca353786c50858f92e31c53f80e69795aa8643b1333be0bef38c5ca96a940aee', NULL),
  ('ch2_KAL-196', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रथम सांस्कृतिक काल की किलेबंदी की दीवारों की मोटाई में समय के साथ क्या बदलाव हुआ?', 'शुरुआती चरण में मोटाई लगभग 1.90 मीटर थी; बाद में भीतर की ओर अतिरिक्त निर्माण से कुल मोटाई लगभग 3–4 मीटर हो गई।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-196 — S16 — printed p. 67 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6bcb2e4290dcb17ad8b84ab8fe54b3a3ed923b585de7b94ecaea24efb71a461e', NULL),
  ('ch2_KAL-197', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के अनुसार प्रथम सांस्कृतिक काल के परकोटे का प्रमुख प्रवेश-द्वार कहाँ बनाया गया था?', 'उत्तर की दीवार के भीतर की ओर मुड़े कोण पर; लेखक ने इसे रक्षा की दृष्टि से उपयोगी माना।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-197 — S16 — printed p. 67 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0a1abb66505374c9e03daa387aa23d0df7525614afaa44aa64ac88d6c3b79da2', NULL),
  ('ch2_KAL-198', 'catalog.rajasthan_history_ancient_history_kalibangan', 'प्रथम सांस्कृतिक काल के उत्तरी प्रवेश-द्वार से बैलगाड़ी यातायात का अप्रत्यक्ष संकेत किन पुरावशेषों से जोड़ा गया?', 'लगभग 5–6 मीटर चौड़े प्रवेश-द्वार के साथ मिले ठोस टेराकोटा के गाड़ी-पहियों और बैल की आकृतियों को गाड़ियों के उपयोग का अप्रत्यक्ष संकेत माना गया।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-198 — S16 — printed p. 67 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '74b8d55b4833482dfe36a9823d5f9722606de8ca2b7e43433e11b181845c8feb', NULL),
  ('ch2_KAL-199', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा के प्रथम सांस्कृतिक काल के घरों और संरचनाओं की कितनी निर्माण-उप-अवधियाँ दर्ज कीं?', 'पाँच निर्माण-उप-अवधियाँ; कुल सांस्कृतिक जमाव लगभग 1.60 मीटर था।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-199 — S16 — printed p. 68 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1cf60c125ff1d56598cd4bb003584b2bb05ddd76b0ef5b126372e4697e55ccce', NULL),
  ('ch2_KAL-200', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा के प्रथम सांस्कृतिक काल के घरों की चिनाई में ईंटें लगाने की किस शैली का उल्लेख किया?', 'एक परत में ईंटों के छोटे सिरों को सामने और अगली परत में उनके लम्बे पार्श्व को सामने रखने की शैली, जिसे अंग्रेजी बंधन पद्धति कहा जाता है।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-200 — S16 — printed p. 68 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '9c6b31916eae5e6742e5775a8efdbff5435ba1565cb5a265a1b16e448648299e', NULL),
  ('ch2_KAL-201', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के अनुसार कालीबंगा के परिपक्व हड़प्पा स्तरों में प्रसिद्ध स्त्री-मूर्ति की कौन-सी श्रेणी उल्लेखनीय रूप से अनुपस्थित थी?', 'मातृदेवी की टेराकोटा प्रतिमाएँ; लेखक ने मोहनजोदड़ो और हड़प्पा के विपरीत कालीबंगा में इनके स्पष्ट अभाव का उल्लेख किया।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-201 — S16 — printed p. 89 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4543269eec849f982a45c3e8543659b25ab7de74224d7b9b3e9267d56256cb90', NULL),
  ('ch2_KAL-202', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा के परिपक्व हड़प्पा काल के टेराकोटा अवशेषों में किन दो आकृतियों को विशेष रूप से उल्लेखनीय बताया?', 'एक भावपूर्ण छोटा मानव-मस्तक और आक्रमण की मुद्रा में दिखाया गया बैल।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-202 — S16 — printed p. 89; Plates XXIV–XXV — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'fc297de3d38d2eb4200418aa234d1afd20933af35068cb0245743fa3c38e326d', NULL),
  ('ch2_KAL-203', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल द्वारा लगभग बीस ताँबे के नमूनों के अध्ययन से कालीबंगा में कांस्य निर्माण के बारे में क्या निष्कर्ष निकाला गया?', 'उनके अनुसार जानबूझकर टिन मिलाकर कांस्य बनाने का प्रमाण नहीं मिला; कुछ नमूनों में थोड़ी टिन मात्रा को उन्होंने अयस्क की अशुद्धि माना। यह निष्कर्ष सीमित नमूना-अध्ययन पर आधारित है।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-203 — S16 — printed p. 90 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'bcee361472f8ae2b2427ea9c26f6f572ac304d3025dded17eba7b30ad17df656', NULL),
  ('ch2_KAL-204', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा के परिपक्व हड़प्पा काल में व्यापार के संकेत किन वस्तुओं से जोड़े?', 'चर्ट के घनाकार बाट, पकी मिट्टी के अंशांकित पैमाने, मुहरों और मुहर-छापों से; उनके अनुसार ये प्रथम सांस्कृतिक काल में अनुपस्थित थे।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-204 — S16 — printed p. 90 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd2f1ce8ae1fd10169bae20f17e06c1d77d78d8dd45e65b7fa4d7417c81b41b2a', NULL),
  ('ch2_KAL-205', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की एक टेराकोटा मुद्रा पर बी. बी. लाल ने किन वस्तुओं की छापों की पहचान की?', 'सरकंडों, गाँठ लगी डोरी और सम्भवतः दो मुहरों की छाप; मुद्रा का पदार्थ मिट्टी था।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-205 — S16 — Plate XXVI, printed pp. 90–92 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'dfb1cfd5ee18a13dd6be748e60eec4e31e3f74a11d3f3d9c91e1adef10740eaa', NULL),
  ('ch2_KAL-206', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा की टेराकोटा मुद्रा से किस सम्भावित पैकिंग प्रक्रिया का अनुमान लगाया?', 'वस्तु को सरकंडों में लपेटकर डोरी से बाँधा जाता था और गाँठ पर गीली मिट्टी लगाकर उस पर मुहर की छाप बनाई जाती थी; यह लेखक की कार्य-व्याख्या है।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-206 — S16 — printed p. 90; Plate XXVI — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4701b1f5cca6e8b68a191ba4baabdb8a87c2cf8640715c074ac3fb028e56a927', NULL),
  ('ch2_KAL-207', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के अनुसार कालीबंगा की एक मुहर पर ‘एकशृंगी’ आकृति कितनी मुद्राओं में दिखाई गई?', 'तीन मुद्राओं में—गर्दन पीछे मोड़कर, ऊपर उठाकर और नीचे झुकाकर; लाल ने टिप्पणी की कि ‘एकशृंगी’ कहे जाने वाले पशु के दो सींग दिखाई देते हैं।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-207 — S16 — printed pp. 90–91 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'adc4313415c2b1672f1a1f7203f15b04ab9cfc432e749d7df9776101b94a3e84', NULL),
  ('ch2_KAL-208', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा की दूसरी विशिष्ट मुहर पर किस दृश्य का वर्णन किया?', 'पीछे मुड़कर देखते बाघ और वृक्ष पर बैठे एक मानव-आकार—सम्भवतः देवता—का दृश्य; देवता की पहचान निश्चित नहीं है।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-208 — S16 — printed p. 91 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'af946424785f58877b582b4d579f987fbb4e85308e595819d72c9645a16a185d', NULL),
  ('ch2_KAL-209', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की बेलनाकार मुहर को लाल ने असामान्य क्यों माना और मेसोपोटामिया से उसका क्या सम्बन्ध सुझाया?', 'बेलनाकार मुहर सामान्य सिंधु-प्रकार से अलग थी; लाल ने मेसोपोटामिया की समकालीन बेलनाकार मुहरों के आधार पर किसी सम्भावित विदेशी व्यापारी या प्रतिनिधि से सम्बन्ध का अनुमान दिया, जिसे सिद्ध तथ्य नहीं मानना चाहिए।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-209 — S16 — printed p. 91; Plate XXVII — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '619ec162af016d57d01b48afd00f8e0ba82ee9a07a0575934d88cba35f368372', NULL),
  ('ch2_KAL-210', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के अनुसार कालीबंगा में लेखन केवल किन वस्तुओं तक सीमित नहीं था?', 'मुहरों और मुहर-छापों तक नहीं; सम्भावित मालिकों के नाम कुल्हाड़ियों जैसे मूल्यवान औज़ारों और साधारण मृद्भांडों पर भी लिखे जाते थे।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-210 — S16 — printed pp. 91–92 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '744ec4b5d19b966b90594822603b587651e4e32043719b9b17b9f63e4e9f91b2', NULL),
  ('ch2_KAL-211', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने परिपक्व हड़प्पा काल में कालीबंगा के परित्याग का कौन-सा सम्भावित कारण सुझाया?', 'घग्घर नदी का जल-प्रवाह घटने या नदी सूखने से जलापूर्ति कम होने की परिकल्पना; उन्होंने बाढ़ या नरसंहार को कालीबंगा के अंत का प्रमाणित कारण नहीं माना।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-211 — S16 — printed p. 93; hypothesis, not settled fact — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2836690b51cbee0a60bacea89783b8ffafd37f7fef68b5feeab63497d72af000', NULL),
  ('ch2_KAL-212', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल के 1979 के अध्याय की असंशोधित रेडियोकार्बन सारणी में प्रथम और द्वितीय सांस्कृतिक काल की अनुमानित समय-सीमाएँ क्या थीं?', 'प्रथम काल लगभग 2400–2250 ईसा पूर्व और द्वितीय काल लगभग 2200–1700 ईसा पूर्व; ये उसी लेख में दी गई असंशोधित रेडियोकार्बन तिथियाँ हैं।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-212 — S16 — printed p. 94 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '99b93cf16bfe0c09451213b04f058def28c1bdd09ce74f47a11cc7d451fbfefb', NULL),
  ('ch2_KAL-213', 'catalog.rajasthan_history_ancient_history_kalibangan', 'उसी लेख में मास्का और क्लार्क के संशोधन लगाने पर प्रथम और द्वितीय सांस्कृतिक काल के अनुमानित समय क्या दिए गए?', 'प्रथम काल लगभग 2900–2700 ईसा पूर्व और द्वितीय काल लगभग 2500–2000 ईसा पूर्व; इन्हें 1979 के लेख के संशोधित अनुमान के रूप में ही पढ़ना चाहिए।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-213 — S16 — printed p. 94 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8e6229afb1f46654228be13197fa859d106ba21852972b16f5a843de74ccc6d3', NULL),
  ('ch2_KAL-214', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल ने कालीबंगा की रेडियोकार्बन तिथियों को बिना जाँच सीधे स्वीकार करने के प्रति क्या सावधानी दी?', 'उन्होंने चेताया कि कार्बन-14 तिथियों को बिना आलोचनात्मक जाँच स्वीकार करने से असंगत परिणाम निकल सकते हैं; सभी तिथियों का विवेकपूर्ण सामूहिक आकलन आवश्यक है।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-214 — S16 — printed pp. 93–94 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '62edd33109282db7d8af8fe1d270d0f368cc6dd6061f43d131c3c1baa9133d3f', NULL),
  ('ch2_KAL-215', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. बी. लाल की 1979 की बसावट-योजना में कब्रिस्तान-टीले का कौन-सा संकेतांक छपा है और यह किन अन्य स्रोतों से अलग है?', 'चित्र 1 में KLB-4 छपा है; हनुमानगढ़ गज़ेटियर और भारतीय पुरातत्व सर्वेक्षण के जोधपुर वृत्त के संग्रहालय-पृष्ठ में इसे KLB-8 कहा गया है। मूल उत्खनन-योजना से पुष्टि होने तक इसे अनसुलझा संकेतांक-विवाद मानें।', 'hi', 'https://ignca.gov.in/Asi_data/64222.pdf', 'KAL-215 — S16 — Fig. 1, printed p. 66; S4 — printed p. 36; S7 — “Harappan Site Kalibangan” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e6626a2d1f9d37f62915e1df2fce3e90e1d1fd863a850d8fb2ba76e6c88b70e0', NULL),
  ('ch2_KAL-216', 'catalog.rajasthan_history_ancient_history_kalibangan', 'इरावतम महादेवन के 1977 के सिंधु लिपि-संकलन में कालीबंगा से कितनी अभिलेखयुक्त वस्तुएँ शामिल की गईं?', 'कुल 99 वस्तुएँ; यह 1977 के संकलन की स्थलवार सूची का आँकड़ा है, 1987 की के-श्रृंखला संदर्भ-सीमा से अलग है।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-216 — S14 — Introduction §4, printed p. 5 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4c793a9c72e0fc73a8fde8ae5c00e3231a66ed0eb6e7e3d31e3c45757de3a41f', NULL),
  ('ch2_KAL-217', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन की 1977 की सारणी में कालीबंगा की 99 अभिलेखयुक्त वस्तुओं का प्रकारवार विभाजन क्या है?', '56 मुहरें, 21 मुहर-छापें, 20 मृद्भांडों पर उत्कीर्ण चिह्न और 2 कांस्य उपकरण।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-217 — S14 — Introduction §6.2, printed p. 6 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'bae7be66dfdd9b17ec498f9d1d282f54b657fbfedf2ad9b98c4896da379bd648', NULL),
  ('ch2_KAL-218', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन के 1977 के संकलन में कालीबंगा से कितने अप्रकाशित अभिलेख शामिल किए गए?', '46 अप्रकाशित अभिलेख; लेखक ने 1976 के संशोधन में लोथल और कालीबंगा के अप्रकाशित अभिलेख शामिल किए थे।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-218 — S14 — Introduction §5.2, printed pp. 5–6; §2.2, p. 3 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd87030243c36254c1403c815fdb0f81e49a436bf44f181db4054d9a40b1aa4b8', NULL),
  ('ch2_KAL-219', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन के 1977 के संकलन में 3,455 छायाचित्रित वस्तुओं में से कितनी हटाकर 2,906 अभिलेखयुक्त वस्तुओं का संकलन बनाया गया?', '549 वस्तुएँ—जिन पर अभिलेख नहीं था या अभिलेख पूरी तरह अनुपस्थित, क्षतिग्रस्त अथवा अपठनीय था।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-219 — S14 — Introduction §5.1, printed p. 6 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '673de4e43694b477a5f2f1571f276a06c7fcae1e22f666067ad003617707d762', NULL),
  ('ch2_KAL-220', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन ने सिंधु लिपि के अभिलेखों वाली वस्तुओं को अध्ययन के लिए किन तीन व्यापक श्रेणियों में बाँटा?', 'मुहरें, मुहर-छापें और अन्य सीधे पढ़ी जा सकने वाली अभिलेखयुक्त वस्तुएँ—जैसे मृद्भांड, लघु पट्टिकाएँ, ताँबे की पट्टिकाएँ, कांस्य उपकरण तथा हाथीदाँत या हड्डी की छड़ें।', 'hi', 'https://kashmirasitis.com/wp-content/uploads/2020/10/Indus-scriptdarend.pdf', 'KAL-220 — S14 — Introduction §6.1, printed p. 6 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ec351876561ee0b26820cf067ece8e0d1342fdf7d6912079285af3e1caf34a1c', NULL),
  ('ch2_KAL-221', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. एम. पांडे ने हड़प्पाई अभिलेखों के अध्ययन में सभी चिह्नों को एक साथ लेने के विरुद्ध क्या कारण दिया?', 'अलग-अलग माध्यमों, स्थलों और काल-स्तरों के चिह्नों में सम्भावित क्षेत्रीय या कालगत भिन्नता हो सकती है; इसलिए संदर्भ के बिना उन्हें समान अर्थ वाला नहीं मानना चाहिए।', 'hi', 'https://ignca.gov.in/Asi_data/63860.pdf', 'KAL-221 — S17 — “Inscribed Harappan Material from Kalibangan”, printed p. 156 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '698679f5793dd79199c0775293224ac78464c8a24770e99eea6a9ec119d61292', NULL),
  ('ch2_KAL-222', 'catalog.rajasthan_history_ancient_history_kalibangan', 'पांडे और बी. बी. लाल ने कालीबंगा की अभिलेखयुक्त सामग्री का अध्ययन किन दो वितरण-आधारों पर करने का प्रयास किया?', 'स्तरक्रम के अनुसार ऊर्ध्वाधर वितरण और बस्ती के अलग-अलग क्षेत्रों में स्थानिक अथवा क्षैतिज वितरण के आधार पर।', 'hi', 'https://ignca.gov.in/Asi_data/63860.pdf', 'KAL-222 — S17 — printed p. 156 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '14bd2092d32f4f92fcd5e947f902632d41aae7350575dc664374a0ca224eef3d', NULL),
  ('ch2_KAL-223', 'catalog.rajasthan_history_ancient_history_kalibangan', 'पांडे के अनुसार कालीबंगा में अभिलेख-अध्ययन की शुरुआत किस क्षेत्रीय विभाजन से की गई?', 'दुर्ग और निचले नगर की अभिलेखयुक्त सामग्री को अलग करके; फिर प्राप्त वस्तुओं को ऊर्ध्वाधर और क्षैतिज रूप से अंकित करने की योजना बनाई गई।', 'hi', 'https://ignca.gov.in/Asi_data/63860.pdf', 'KAL-223 — S17 — printed p. 157 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '13f8fb89b5ca6653b128afb72a11020c0d1ec5c9f736e6eb4386213e9433b1b0', NULL),
  ('ch2_KAL-224', 'catalog.rajasthan_history_ancient_history_kalibangan', 'बी. एम. पांडे ने 1978 में कालीबंगा के किन दो प्रकार के चिह्नों को उस समय तक स्थल-विशिष्ट बताया?', 'वनस्पति जैसे और त्रिकोणीय चिह्न; उनके अनुसार वे अन्य हड़प्पाई स्थलों पर प्रयुक्त होते नहीं दिखे, लेकिन यह सीमित साक्ष्य पर आधारित सम्भावना है।', 'hi', 'https://ignca.gov.in/Asi_data/63860.pdf', 'KAL-224 — S17 — printed p. 156 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e85874b9d447445d7b2f0bfe74b38b48eed36f35aebf38469a5e499af880be76', NULL),
  ('ch2_KAL-225', 'catalog.rajasthan_history_ancient_history_kalibangan', 'महादेवन और पांडे के अनुसार एक ओर अभिलेख तथा दूसरी ओर पशु या मानव आकृति अथवा प्रतीक वाली ताँबे की पट्टिकाएँ किस हड़प्पाई स्थल से मिली थीं?', 'मोहनजोदड़ो से; पांडे ने लिखा कि कालीबंगा सहित अन्य हड़प्पाई स्थलों पर ऐसी ताँबे की पट्टिकाएँ नहीं मिली थीं।', 'hi', 'https://ignca.gov.in/Asi_data/63860.pdf', 'KAL-225 — S17 — printed p. 156; S14 — Introduction §6.2, printed p. 6 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '5d3c7832e7bf5de59aada54626241a7f30f77a6f00cb8dfbc459102606109af4', NULL),
  ('ch2_KAL-226', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण की 2017–18 की रिपोर्ट में कालीबंगा के जीव-अवशेष अध्ययन के अंतर्गत लगभग कितने नमूनों पर काम किया जा चुका था?', 'लगभग 1,400 नमूनों पर; यह परियोजना की शुरुआती प्रगति का आँकड़ा था।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2017_18.pdf', 'KAL-226 — S18 — Annual Report 2017–18, project “Zooarchaeology of faunal remains of Kalibangan”, printed p. 45 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'edb12d5d3ff18d415bbb037f23edaa3e79f1f33a775d7810a2a31d41a6d7654c', NULL),
  ('ch2_KAL-227', 'catalog.rajasthan_history_ancient_history_kalibangan', 'भारतीय प्राणी सर्वेक्षण की 2017–18 की रिपोर्ट में कालीबंगा के कितने जीव-अवशेष नमूनों की पहचान और पंजीकरण पूरा हुआ था?', '612 नमूने; रिपोर्ट के अनुसार वे स्तनधारियों की 6 प्रजातियों, 6 वंशों, 3 कुलों और 2 गणों से सम्बन्धित थे।', 'hi', 'https://zsi.gov.in/uploads/documents/importantLinks/english/Annual_Report_2017_18.pdf', 'KAL-227 — S18 — Annual Report 2017–18, project entry, printed p. 45 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'eecdd0cbfa9036a1eb9300410dd7d89a83055b016ed0dd20e274ff1086092e7a', NULL),
  ('ch2_KAL-228', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-775921 में कालीबंगा की किस प्रकार की पुरावस्तु दर्ज है?', 'पहिए लगाने के लिए छेद वाला टेराकोटा बैल; सूची में इसे हड़प्पाई शैली की प्रागैतिहासिक प्रदर्शनीय वस्तु बताया गया है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-228 — S19 — NMMA, Archaeological Museum Kalibangan, record GM-KAM-RJ-775921 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b82dfc00e774f2311f37628da4290931249dbb1c7fff69a988416f354f2a8d46', NULL),
  ('ch2_KAL-229', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-775921 में टेराकोटा बैल के क्या माप दर्ज हैं?', 'लगभग 10.00 × 4.60 × 3.60 सेंटीमीटर (लम्बाई × चौड़ाई × ऊँचाई)।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-229 — S19 — record GM-KAM-RJ-775921, measurement fields — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '63cd70bcd87f4ce584b710c06f2267c56b46bc4390accc518f503d911762dc4d', NULL),
  ('ch2_KAL-230', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-761412 में KLB-1 के प्रारम्भिक स्तर से मिली किस पशु-आकृति का वर्णन है?', 'चार जुड़े हुए पैरों, छोटी गर्दन और कूबड़ वाली छोटी टेराकोटा बैल-आकृति; अभिलेख इसे KLB-1 के प्रारम्भिक स्तर से प्राप्त बताता है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-230 — S19 — record GM-KAM-RJ-761412, description and provenance fields — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '66dbb50805d6f4dbffb072753d5d5fd0b0911cc3673c48bbe23c77f28f8229f3', NULL),
  ('ch2_KAL-231', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-1393795 में लाल टेराकोटा बैल के टूटे भाग पर कितने छेद दर्ज हैं?', 'पाँच—दो गर्दन के दोनों ओर और तीन कूबड़ पर; अभिलेख में सींग टूटे हुए और निचला शरीर अनुपस्थित बताया गया है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-231 — S19 — record GM-KAM-RJ-1393795, description field — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd03e71f22d1d1a869164740b108a417fda97e375df863fe29ddb92ae6fe5b65c', NULL),
  ('ch2_KAL-232', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-1393288 की टेराकोटा भैंस-आकृति में कौन-सी क्षति और विशेषताएँ दर्ज हैं?', 'आगे की ओर मुड़े हुए टूटे सींग, माथे पर एक छेद और टूटा हुआ शरीर; सूची के अनुसार चेहरे की विशेषताएँ स्पष्ट नहीं हैं।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-232 — S19 — record GM-KAM-RJ-1393288, description field — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8c73176bd704bd2d05e657517ee322b0b098cfbf3595b4fc982582ff892cb721', NULL),
  ('ch2_KAL-233', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-1393832 में दर्ज अलंकृत टेराकोटा बैल-मस्तक पर कौन-से सजावटी चिह्न बताए गए हैं?', 'पत्ती जैसी आँखें, माथे पर तिरछी खुदी रेखाएँ, गर्दन पर संकेंद्रित वृत्त और मोटी पट्टी जैसा अलंकरण; सिर पर क्षैतिज छेद भी दर्ज है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-233 — S19 — record GM-KAM-RJ-1393832, description field — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '053bf536d6cce85ceec3eac34f4bef1be854552d5ec66c6a4e50429686c12fd3', NULL),
  ('ch2_KAL-234', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-775637 में दर्ज टेराकोटा गाड़ी का निर्माण किस प्रकार बताया गया है?', 'सूची इसे हाथ से बनाई गई टेराकोटा गाड़ी बताती है; वस्तु टूटी हुई है और इसमें छेद दर्ज हैं।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-234 — S19 — record GM-KAM-RJ-775637, description and condition fields — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'da5a0ff40afeb0d4f117c059e884a8b3735bfb6fc106545f1353db05567c3cb8', NULL),
  ('ch2_KAL-235', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-775897 की टेराकोटा पक्षी-आकृति की संरचना कैसी दर्ज है?', 'लगभग 4.00 × 2.70 × 2.20 सेंटीमीटर की खोखली पक्षी-आकृति, जिसमें एक छेद है; सूची इसे टूटी हुई बताती है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-235 — S19 — record GM-KAM-RJ-775897, measurement and description fields — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3c884b27c3d210a1b4c2139112b2977f8fb1bcc392cee15d2b176c7dd93576a3', NULL),
  ('ch2_KAL-236', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन की सूची में GM-KAM-RJ-776047 नामक टेराकोटा वस्तु किस शीर्षक से दर्ज है?', '‘पकी मिट्टी की पक्षी-सीटी’ शीर्षक से; सूची में इसका विवरण उपलब्ध नहीं है और स्थिति टूटी हुई दर्ज है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-236 — S19 — record GM-KAM-RJ-776047, title and description fields — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '7765c3ba6357ddabf6bc7da92b2cff4eb999e76c0515c393dad4170df69dfe00', NULL),
  ('ch2_KAL-237', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-775543 की टेराकोटा खाट के बारे में क्या विवरण दिया गया है?', 'हाथ से बनी टेराकोटा खाट, जिसकी केवल एक टाँग बची हुई है; दर्ज माप लगभग 10.10 × 6.10 × 1.40 सेंटीमीटर हैं।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-237 — S19 — record GM-KAM-RJ-775543, measurement and description fields — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e7087fc5720e3acf83af036891448bda9820414c8294639366bb824c716d66f6', NULL),
  ('ch2_KAL-238', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-1392979 की टेराकोटा चारा-प्याली की पहचान किन विशेषताओं से होती है?', 'छोटी, आंशिक रूप से मटमैले लाल और धूसर रंग की, पतले सीधे किनारे तथा टोंटी वाली टूटी प्याली; इसे अच्छी तरह परिष्कृत मिट्टी से बना बताया गया है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-238 — S19 — record GM-KAM-RJ-1392979, description field — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '226cea8c9c03a64c1891f8c75889ce242efa652e7b7f0e8cf19a51a74f8275dd', NULL),
  ('ch2_KAL-239', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-1391780 की टेराकोटा मापनी पर किस प्रकार के निशान दर्ज हैं?', 'लम्बे और चिकने पिंड पर खुदी हुई खड़ी रेखाओं के दो समूह तथा वृत्ताकार अनुप्रस्थ काट; सूची इसे मापन के लिए प्रयुक्त मापनी बताती है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-239 — S19 — record GM-KAM-RJ-1391780, description field — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a0956537769b89c21ab923a9b61116dd8fdb928d7220293eaeecb355a7b25101', NULL),
  ('ch2_KAL-240', 'catalog.rajasthan_history_ancient_history_kalibangan', 'राष्ट्रीय स्मारक एवं पुरावशेष मिशन के अभिलेख GM-KAM-RJ-770761 के गोल टेराकोटा खंड को किस सम्भावित उपयोग से जोड़ा गया है?', 'सूची इसे सम्भवतः जाल का भार मानती है; वस्तु हाथ से बनी और टूटी हुई है तथा उसका लगभग एक-चौथाई भाग ही उपलब्ध बताया गया है।', 'hi', 'https://nmma.nic.in/nmma/exploreMusObject.do?musname=GM-KAM&object=101', 'KAL-240 — S19 — record GM-KAM-RJ-770761, description and condition fields — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1bae76110e0b5d7fa2ed722f91579063aee03ad17faddf89b0aa581fc212b773', NULL),
  ('ch2_KAL-241', 'catalog.rajasthan_history_ancient_history_kalibangan', 'ASI Part II के Chapter 22 के अनुसार कालीबंगा के cemetery में कितने extended burials दर्ज किए गए?', '88 extended burials।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-241 — S6 — Ch. 22, printed p. 1422 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b86c56b37f3982abc89ca5da8d47040a744bb654b4c97a10437bdec358c88208', NULL),
  ('ch2_KAL-242', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के extended burials को कितने समूहों में दर्ज/plot किया गया?', '16 समूहों में।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-242 — S6 — Ch. 22, printed p. 1422 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '271c0d71cf819ef2bf3786981ff2b563065281f3092d6252ffd8fb44b0d22cbe', NULL),
  ('ch2_KAL-243', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Chapter 22 के अनुसार प्रत्येक burial-group में सामान्यतः कितने extended burials थे?', 'प्रत्येक समूह में लगभग 6–10 extended burials और कम-से-कम एक बड़ा rectangular pit बताया गया है; समूहों को अलग परिवारों से जोड़ना लेखक की परिकल्पना है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-243 — S6 — Ch. 22, printed p. 1422; family interpretation is tentative — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b466ee9ac75f91a576108d124ca1104d0352270db6cb64778cca05b1ed69521e', NULL),
  ('ch2_KAL-244', 'catalog.rajasthan_history_ancient_history_kalibangan', 'skeletal remains के बिना बड़े rectangular/oblong burial pits की संख्या कितनी दर्ज की गई?', '14 pits।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-244 — S6 — Ch. 22, printed p. 1423 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '74d9b4ecb82c634b57cffbb1eb95a943bf09be872c28c691a75d6e6b83a8a35d', NULL),
  ('ch2_KAL-245', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा cemetery में pot-burial क्षेत्र extended-burial क्षेत्र के किस ओर स्थित था?', 'extended-burial क्षेत्र के उत्तर में।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-245 — S6 — Ch. 22, printed p. 1422; Ch. 23, printed p. 1429 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8959478e862b90d98c8a4945f06d971ca7255fb0cf6857ad2322e0abe8b76618', NULL),
  ('ch2_KAL-246', 'catalog.rajasthan_history_ancient_history_kalibangan', 'खुले बड़े burial pits में समय के साथ किस प्रकार की मिट्टी/अवसाद-परतें जमा हुईं?', 'पतली-मोटी clay और sand की परतें; रिपोर्ट इन्हें pit के खुले रहने के दौरान क्रमशः भराव के रूप में दर्ज करती है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-246 — S6 — Ch. 22, printed p. 1422 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'bc516a87e7bd7dd57ba9c29bd2b0959673ee7f95a4918fa019595f5f07344932', NULL),
  ('ch2_KAL-247', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के pot-burial pits की सामान्य माप-सीमा क्या दर्ज है?', 'पूर्व-पश्चिम व्यास लगभग 1.30–2 मीटर, उत्तर-दक्षिण व्यास 1.17–2 मीटर और गहराई 0.30–0.63 मीटर।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-247 — S6 — Ch. 23, printed p. 1429 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '84bcd2694a99b48e2406f4647ac54ec813f30f6d12c364d7ddba03bd0565722b', NULL),
  ('ch2_KAL-248', 'catalog.rajasthan_history_ancient_history_kalibangan', 'पाँच pot burials में urn को pit के किस भाग में रखा गया था?', 'pit के पश्चिमी किनारे के पास, बीच में नहीं।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-248 — S6 — Ch. 23, printed p. 1429 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'fb51ab16e11512b9bdeb96076a95ef8f3e5d622381a195a3a2a3d9221f62054d', NULL),
  ('ch2_KAL-249', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 1 के urn को किस प्रकार ढका गया था?', 'तीन lids (triple lid) से।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-249 — S6 — Ch. 23, printed p. 1429 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b1e054bee0c28ad8f820730740334e01b0cff43fc463fff1b668b4af9ef6c022', NULL),
  ('ch2_KAL-250', 'catalog.rajasthan_history_ancient_history_kalibangan', 'pot burials में urn के अंदर मानव-अस्थियों का अपवाद किस burial में दर्ज है?', 'Burial 3 में एक molar और कुछ टूटे हुए bone fragments मिले; अन्य urns में हड्डियाँ दर्ज नहीं थीं।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-250 — S6 — Ch. 23, printed p. 1429 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ec05dd610d87bf148673c8e3ebb720e35f94ff83db074a7b7ecfbb03ceabf183', NULL),
  ('ch2_KAL-251', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 2 की प्रमुख विशेषताएँ क्या थीं?', 'urn नहीं था; pit के उत्तरी आधे भाग में सात बर्तन रखे गए थे।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-251 — S6 — Ch. 23, printed pp. 1433–1434 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '11d6d2872a74723224731791770057dd665c5a6f7f17a84f58f30f14b0439d1c', NULL),
  ('ch2_KAL-252', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 3 में बर्तनों की परतों और urn की स्थिति कैसी थी?', 'बर्तन दो स्तरों में रखे थे; urn निचले स्तर में था और pit में 20 से अधिक बर्तन मिले।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-252 — S6 — Ch. 23, printed pp. 1436–1437 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '31bec2ba4d19435c8f1a3ee7d891c7e51728b3bd979efa238e96bd6fd41b0507', NULL),
  ('ch2_KAL-253', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 16 में कितने बर्तन और कौन-सा विशेष आभूषण मिला?', '29 बर्तन और तीन टुकड़ों में टूटी एक shell bangle।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-253 — S6 — Ch. 23, printed pp. 1449–1450 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c61073732905bee1f0a36011830c8d3f8b11478d5a379c2edd3662d810234fb9', NULL),
  ('ch2_KAL-254', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Extended Burial 29 के ईंट-निर्मित burial chamber की बाहरी और भीतरी माप क्या थीं?', 'बाहरी माप लगभग 4 × 2 मीटर और भीतरी माप लगभग 3.20 × 1.28 मीटर; इसे mud-brick courses से बनाया गया था।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-254 — S6 — Ch. 22, printed pp. 1365–1366 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '18082e7d82743c2b9771bb1c06af62f0ea38bf3581726b7a00c498a70a29bf2e', NULL),
  ('ch2_KAL-255', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Burial 29 के ईंट-निर्मित chamber की तुलना A.K. Sharma ने किस स्थापत्य अवधारणा से की?', 'लेखक ने इसकी तुलना *bhumi-griha* से की; यह उनकी व्याख्यात्मक तुलना है, निर्विवाद पहचान नहीं।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-255 — S6 — Ch. 22, printed p. 1424 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'bafcb3a4dc45bfaa9a6f3018d21c4cf40e5e4b90a62a04070f6aafd7f64b4a41', NULL),
  ('ch2_KAL-256', 'catalog.rajasthan_history_ancient_history_kalibangan', 'rectangular pottery-only Burial 33 में कितने बर्तन दर्ज किए गए?', '78 बर्तन।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-256 — S6 — Ch. 22, printed pp. 1399–1400 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'f1fe848cc3247d8a72b70510c675d3db1c1529ef6c378d3dc27e9b15a7939fa6', NULL),
  ('ch2_KAL-257', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Burial 33 के pottery assemblage में किन प्रमुख प्रकार के पात्रों का उल्लेख है?', 'Dish-on-stand, cup-on-stand, shallow plates, पतले glasses, narrow-mouthed और S-shaped jars, handi तथा straight-necked jars।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-257 — S6 — Ch. 22, printed pp. 1399–1400 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '973cf2f10f09e0fe1ac7d9ae2e02e62df7cbc530f9c4895c0767ed14bcb6429e', NULL),
  ('ch2_KAL-258', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Chapter 22 के लेखक के अनुसार 1963–64 season के मानव-अस्थि-अवशेष किस संस्था को भेजे गए थे?', 'Anthropological Survey of India, Calcutta को; लेखक ने लिखा कि उनका अध्ययन उनके द्वारा नहीं किया गया।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-258 — S6 — Ch. 22, printed pp. 1401–1402 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '14ca7892df379b79653f04dee26237d89cdefe9727527298164a16eb20f70f2a', NULL),
  ('ch2_KAL-259', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा cemetery की palaeo-pathological व्याख्याओं में लेखक ने कौन-सी सावधानी बताई?', 'गहन clinical training के बिना diagnosis की निश्चितता कठिन है; अधिकांश skeletons में मृत्यु का कारण बताने वाला स्पष्ट चिह्न नहीं था।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-259 — S6 — Ch. 22, printed pp. 1401–1402 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'df91f92a004a80c16949496d96dcfb54eca55d6beac541a114c2c8ee8d23e71d', NULL),
  ('ch2_KAL-260', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Burial 9 के बालक के skull के बारे में A.K. Sharma ने कौन-सी संभावित स्थिति और cranial marks दर्ज किए?', 'लेखक ने hydrocephalus की संभावना बताई और दाएँ temporal क्षेत्र में कान के ऊपर तीन छोटे trephined holes दर्ज किए; यह लेखक की व्याख्या है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-260 — S6 — Ch. 22, printed pp. 1402–1403 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ddccd8307db75a0c269b0b4a83aedbf07d25f44247bcafba12b786762e5601fa', NULL),
  ('ch2_KAL-261', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Burial 11 के वयस्क कंकाल की किन हड्डियों पर sharp cut marks दर्ज किए गए?', 'बाईं femur और tibia के भीतरी भाग पर; घावों में healing के संकेत नहीं बताए गए।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-261 — S6 — Ch. 22, printed pp. 1409–1410 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4bc1931b4ad325f5449e8e5c3334554d72efe0d43f43affaf923fe26fcb42c45', NULL),
  ('ch2_KAL-262', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Burial 26 के वयस्क की बाईं भुजा की हड्डियाँ दाईं ओर की तुलना में कितनी छोटी दर्ज की गईं?', 'बाईं radius लगभग 2.8 सेमी और ulna लगभग 3.6 सेमी छोटी बताई गई।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-262 — S6 — Ch. 22, printed pp. 1416–1417 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3a6894d3ccf9fb9b3ca2efa94038abbb4a9eaa448f79aef31f6443020e041c02', NULL),
  ('ch2_KAL-263', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Burial 10 की left humerus पर कौन-सा असामान्य निशान दर्ज किया गया?', 'गोलाकार burning mark; लेखक ने इसे संभवतः आकस्मिक और शायद गैर-घातक माना, पर यह निश्चित निष्कर्ष नहीं है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-263 — S6 — Ch. 22, printed p. 1415 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd79fec55a10bedc9127b5b8eeabebcf8efec81dde29693351f627997de08587f', NULL),
  ('ch2_KAL-264', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Chapter 22 के Case VIII में शव की असामान्य स्थिति और साथ मिले पात्रों की संख्या क्या थी?', 'शव उल्टी/असामान्य crouched स्थिति में, सिर दक्षिण की ओर था और उसके साथ केवल तीन बर्तन दर्ज थे; लेखक की paralytic संबंधी व्याख्या को संभावना ही मानें।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-264 — S6 — Ch. 22, printed pp. 1419–1420 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '350e622942e8cf57f9d9a48b00b2ca416d5496a8cb83f5b4a68815505f3314b3', NULL),
  ('ch2_KAL-265', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 1 में urn सहित कुल कितने बर्तन दर्ज किए गए और वे किस ware के थे?', 'कुल 23 बर्तन; सभी red ware के थे।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-265 — S6 — Ch. 23, printed p. 1432 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '23bc1e15fdc726d68705e02b67502e78a92d08dcf711e6bc9c9eaa453a0df561', NULL),
  ('ch2_KAL-266', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 1 के urn पर कौन-सा pre-firing graffiti mark दर्ज है?', 'आयताकार सीमा के भीतर कई cross-lines का चिह्न।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-266 — S6 — Ch. 23, printed p. 1432 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '86813daf7413b08e4bd760a5a9575279ce926d628f2da6d28e11c20333f6e432', NULL),
  ('ch2_KAL-267', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 6 में कितने pots और कितनी faience वस्तुएँ मिलीं?', '21 pots और दो faience objects; लेखक ने उनके संभावित उपयोग को ear ornament और pendant माना, पर यह अनुमान है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-267 — S6 — Ch. 23, printed pp. 1439–1440 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '03ab3c2a3b06bf92a60f829e07460aba99aa5eebc271535985abede3ebd17105', NULL),
  ('ch2_KAL-268', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 7 से कौन-से beads और shell ornament मिले?', 'पाँच carnelian beads, एक jasper bead और एक पूरी shell bangle।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-268 — S6 — Ch. 23, printed p. 1442 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b6e619daf28749af8c19862704d63cd79c8494e27c4a15441eda75e7c9669a80', NULL),
  ('ch2_KAL-269', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burials 6, 7 और 17 का सापेक्ष stratigraphic क्रम क्या बताया गया है?', 'Burial 6 पहले का है; Burial 7 और 17 ने उसे काटा, इसलिए रिपोर्ट उन्हें बाद का और संभवतः परस्पर समकालीन मानती है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-269 — S6 — Ch. 23, printed p. 1431 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a8640d58f0b1842477d891a1e983192e7fa93d38d093a4ebf672c99f9a0c62a8', NULL),
  ('ch2_KAL-270', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 13 में associated pottery किस प्रकार दो स्तरों पर रखी गई थी?', 'ऊपरी स्तर के बर्तन पूर्व-पश्चिम रेखा में थे; दूसरा स्तर लगभग 0.25 मीटर नीचे मिला।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-270 — S6 — Ch. 23, printed pp. 1444–1445; urn description has an internal report inconsistency — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '368f300a92551bdbe1ac15675ee21c178e8645166544ae79131f8f46b30e600a', NULL),
  ('ch2_KAL-271', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 15 के pit की माप और प्रमुख प्राप्ति क्या थी?', 'अनियमित pit लगभग 1.75 मीटर लंबा और 1 मीटर चौड़ा, बहुत उथला था; केवल एक shallow plate पहचानी गई और अन्य पुरावस्तु नहीं मिली।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-271 — S6 — Ch. 23, printed p. 1447 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '559e4a32502f25f90641dc0a52bdd597b3da49359a2976b430c78bd329a94387', NULL),
  ('ch2_KAL-272', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 17 में urn और बर्तनों की संख्या के बारे में क्या दर्ज है?', 'कोई urn नहीं मिला; कुल आठ बर्तन दर्ज किए गए।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-272 — S6 — Ch. 23, printed p. 1453 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c0f746292eb2d4639cfa686a8f64b97d597c0fee69980ee4e12a8638a284c416', NULL),
  ('ch2_KAL-273', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 18 की अधिकतम गहराई और सुरक्षित ढक्कन की स्थिति क्या थी?', 'अधिकतम गहराई लगभग 0.15 मीटर थी और केवल एक lid साबुत मिला; अन्य पात्रों के टूटे टुकड़े थे।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-273 — S6 — Ch. 23, printed p. 1455 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '66f5151120e7d8b65e76ab6dfd57233ef32b8a7db24f792175f8efaf6c7d5633', NULL),
  ('ch2_KAL-274', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 20 में कौन-से दो पात्र मिले?', 'एक urn और एक बहुत बड़ा dish-on-stand; लेखक ने दूसरे को अब तक मिले सबसे बड़े/ऊँचे उदाहरणों में माना।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-274 — S6 — Ch. 23, printed p. 1457 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'f8866bcb3e96c42f753010e06fed56a43b00d5038e603b2f25a546cf013a1221', NULL),
  ('ch2_KAL-275', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 23 में urn और associated pottery की व्यवस्था कैसी थी?', 'urn लगभग बीच में था और उसके दोनों ओर 13 associated pots रखे थे; ऊपरी सतह हल चलने से क्षतिग्रस्त थी।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-275 — S6 — Ch. 23, printed p. 1459 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4947e9897bcda20d650a79c3f6e90b3dd59fbabb708a09fcc1fdd0ac9503af35', NULL),
  ('ch2_KAL-276', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Oblong Pot Burial 24 से कितने बर्तन मिले और pit की दिशा क्या थी?', '48 बर्तन; pit उत्तर-दक्षिण दिशा में था और लगभग 3.32 × 1.30 × 1.05 मीटर मापा गया।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-276 — S6 — Ch. 23, printed pp. 1460–1461 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2b0e143fe6945e8e60f5389c4a330d1e48afae69707c373fb48695aaa66990b1', NULL),
  ('ch2_KAL-277', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Oblong Pot Burial 25 में कितने pots और किस दिशा में pit दर्ज किया गया?', '14 pots; लगभग 3.10 मीटर लंबा, अधिकतम 1.30 मीटर चौड़ा और 1.17 मीटर गहरा pit उत्तर-दक्षिण दिशा में था।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-277 — S6 — Ch. 23, printed p. 1462 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '09692139a5666ebc50e28569396380174943ed12a0e49c1528f34224d1959053', NULL),
  ('ch2_KAL-278', 'catalog.rajasthan_history_ancient_history_kalibangan', 'Pot Burial 25 की laminations में कौन-सी तीन अलग deposits पहचानी गईं?', 'compact सफेद महीन clay, भूरी परत और fine sand; लेखक ने इन्हें हवा और पानी से आए deposits बताया।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-278 — S6 — Ch. 23, printed pp. 1462–1463 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3e3f0d9e9e2c628e339bd1561751664e4f254ff914856342e0a54b64f40c7f93', NULL),
  ('ch2_KAL-279', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-8 cemetery की pottery बनाने की तकनीक और firing के बारे में Chapter 24 क्या बताता है?', 'pottery पूरी तरह wheel-turned, अच्छी तरह levigated clay से बनी और mature firing वाली बताई गई है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-279 — S6 — Ch. 24, printed p. 1467 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b9af3f1c57100f8fcd76a7357f4f7b1d2d20af4bd2fd0cc846ce716120dc7faf', NULL),
  ('ch2_KAL-280', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-8 cemetery pottery assemblage में कौन-सा ware नहीं मिला?', 'Grey ware का कोई specimen नहीं मिला।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-280 — S6 — Ch. 24, printed p. 1467 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1f281ce68bfd3a24423347fd587b6687fe772f1e622254ce4e1b3376dda75789', NULL),
  ('ch2_KAL-281', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-8 cemetery में perforated jar की विशेषता क्या थी?', 'बिना skeletal remains वाले एक rectangular burial में perforated jar के भीतर छोटा vase रखा मिला; रिपोर्ट इसे cemetery का solitary find बताती है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-281 — S6 — Ch. 24, printed p. 1467 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '632e91072bf65f8d87aa5b0d26e21269c6fc0bc6d0f8c0d70fcf1b2b26b6356e', NULL),
  ('ch2_KAL-282', 'catalog.rajasthan_history_ancient_history_kalibangan', 'ASI Part II के अनुसार KLB-8 cemetery burials से terracotta cakes मिले थे या नहीं?', 'नहीं; Chapter 24 के अनुसार cemetery burials से terracotta cakes नहीं मिले।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-282 — S6 — Ch. 24, printed p. 1467 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '05ac53c8f9b7a6f990d8ac46bcbc8d927854e7aa5a7e486e96a6dd0c8f0cc097', NULL),
  ('ch2_KAL-283', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के KLB-8 कब्रिस्तान की विस्तारित कब्र संख्या 10 से कौन-सी ताँबे की वस्तु मिली?', 'ताँबे का दर्पण; विवरण में इसकी कुल लंबाई लगभग 11 सेमी और दर्पण वाले भाग का व्यास लगभग 6 सेमी दिया गया है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-283 — S6 — Ch. 25, “Copper Objects”, printed pp. 1475–1476; exact grave-context and measurements need independent re-check. — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '633b8c16a76baed98d053740a76b28c952ba00d79cd221020240e79a0ec751bf', NULL),
  ('ch2_KAL-284', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-8 कब्रिस्तान के छोटे पुरावशेषों में किस आकृति का फायेंस का साहुल मिला?', 'कली के आकार का फायेंस का साहुल, जिसकी ऊँचाई लगभग 7 सेमी बताई गई है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-284 — S6 — Ch. 25, “Faience Objects”, printed pp. 1477–1478. — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'eaf5703d311a977143428d4c9ccdd0244601f42bfcf445efae95946943b76d0d', NULL),
  ('ch2_KAL-285', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-8 कब्रिस्तान की किस कब्र से लगभग 4 सेमी व्यास वाला शंख/सीप का कर्णाभूषण मिला?', 'कब्र संख्या 28 से; इसे कान के छल्ले या बाले के रूप में वर्णित किया गया है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-285 — S6 — Ch. 25, “Shell Objects”, printed pp. 1480–1481. — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '726c248fb709f74c59e31d12749929f2a65574ba06b5105862072142ccbebccb', NULL),
  ('ch2_KAL-286', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के कब्रिस्तान से मिले अकीक के एक बाट का दर्ज भार कितना था?', 'लगभग 0.874 ग्राम।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-286 — S6 — Ch. 25, “Agate, Bone and Terracotta Objects”, printed pp. 1482–1483; केवल रिपोर्ट में दर्ज मान, स्वतंत्र मापन नहीं। — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'cae91b4ef18dd3f6b4eeeff77c6234beedcafef90f8e9eda864f49627dba1f72', NULL),
  ('ch2_KAL-287', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-8 कब्रिस्तान की स्वर्ण मनकियों के प्रमुख आकार कौन-से थे?', 'गोल द्विशंक्वाकार, लंबी द्विशंक्वाकार, पीपे जैसी और नलिकाकार मनकियाँ; कब्र संख्या 22 से स्वर्ण का एक अलग टुकड़ा भी दर्ज है।', 'hi', 'https://asi.nic.in/pdf/Excavation-at-Kalibangan-Part-II-min-1-compressed_compressed.pdf', 'KAL-287 — S6 — Ch. 25, “Gold Objects”, printed pp. 1486–1487. — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6aae739c3b5a554ae95bc5da4d218f427f4778dffc47f5dff2efbe252a0594c7', NULL),
  ('ch2_KAL-288', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के किलेबंदी-द्वारों पर सुरक्षा के लिए कौन-सी व्यवस्था थी?', 'द्वारों के साथ प्रहरी-कक्ष बनाए गए थे।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-288 — S22 — “General Features of Structures”, printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e46459e36a16f004e1cffa821a5f34aff5bca265fb8cc91da79db3f1b1ab2b22', NULL),
  ('ch2_KAL-289', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की सड़कों की सतह/भराव को मजबूत करने के लिए किन वस्तुओं का उपयोग किया गया?', 'कच्ची ईंटों और टेराकोटा केक का सड़क-भराव सामग्री के रूप में उपयोग हुआ।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-289 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b8cc73589394b918cfa5ca0460ac83941da9fca2c66f1cc9b3011b224209fe15', NULL),
  ('ch2_KAL-290', 'catalog.rajasthan_history_ancient_history_kalibangan', 'रिपोर्ट के अनुसार पकी ईंटों का सीमित उपयोग मुख्यतः कहाँ हुआ और इसका संभावित कारण क्या था?', 'पकी ईंटें नालियों में प्रयुक्त हुईं; रिपोर्ट इसका संभावित कारण उनकी अधिक लागत बताती है।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-290 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd56bf33b8290f04cef16d1f8510f6cdaf6a52410bd1cd641a4b78d5b5d079a96', NULL),
  ('ch2_KAL-291', 'catalog.rajasthan_history_ancient_history_kalibangan', 'नालियों को छोड़कर सामान्य ईंट-चिनाई में ईंटों की पंक्तियों का कौन-सा क्रम मिलता है?', 'एक पंक्ति शीर्ष-दिशा में रखी ईंटों (headers) की और अगली पंक्ति लंबाई-दिशा में रखी ईंटों (stretchers) की होती थी।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-291 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8195b09fb0aa629f9f266c2c56281ced514ad0c1654e7e4eda813f88ba9d40df', NULL),
  ('ch2_KAL-292', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कुछ क्षेत्रों में घर की सड़क की ओर वाली दीवार किस दोहरी भूमिका में काम करती थी?', 'वही सड़क-दीवार घर की मुख्य दीवार का काम भी करती थी।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-292 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '41ec787d1504f5db35b8750871ce82ba091fe705fa59067c737099133bb9f06f', NULL),
  ('ch2_KAL-293', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के कुछ आवासीय क्षेत्रों में सड़क-दीवार के अलावा कौन-सी अतिरिक्त दीवार-व्यवस्था मिली?', 'कुछ स्थानों पर घर की अलग दूसरी दीवार भी बनाई गई थी।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-293 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b17183dd6798c2f465779fd7b5cc66ce9bd6b918ce4bda23e79f071289def3cc', NULL),
  ('ch2_KAL-294', 'catalog.rajasthan_history_ancient_history_kalibangan', 'घरों और सड़क-दीवारों की क्षतिग्रस्त जगहों की मरम्मत में किन सामग्रियों का सहारा लिया जाता था?', 'खाली जगहों को मिट्टी से भरकर उसमें बर्तन-खंड, कोयला और बजरी मिलाई/लगाई जाती थी।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-294 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ed2bc7422117e76b33f2e6b582f57e35f1c2d08fb3706ee861c86e10bd9f6a40', NULL),
  ('ch2_KAL-295', 'catalog.rajasthan_history_ancient_history_kalibangan', 'D-3 ग्रिड 3 के उत्खनित घर में दर्ज एक द्वार की चौड़ाई लगभग कितनी थी?', 'लगभग 90 सेंटीमीटर।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-295 — S22 — printed p. 130; D-3, Grid 3 trench entry — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2376a7036fc608c4463140f3ef2f9ca14c0cf601fb50748e6ef9911ec712bc5a', NULL),
  ('ch2_KAL-296', 'catalog.rajasthan_history_ancient_history_kalibangan', 'उत्खनित कमरों में कौन-से आकार के कमरे अधिक मिले और उनका औसत क्षेत्रफल कितना था?', 'छोटे चौकोर कमरे अधिक थे; कई कमरों का क्षेत्रफल लगभग 5 वर्गमीटर या उससे कम था।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-296 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c44ac954c563c8e4d2f985bb4b8adfb00984c3cb29feffc5cbea51e6e078424a', NULL),
  ('ch2_KAL-297', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के घरों में सीढ़ियों के अवशेष किस प्रकार की इमारतों का संकेत देते हैं?', 'कुछ घर एक या दो मंज़िल के थे; सीढ़ियाँ पहली मंज़िल तक जाने के लिए थीं।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-297 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '65410594998ffdffd8e30155c05b25b0e2ac391e1e476d01fc4a2aa4a4dadc0a', NULL),
  ('ch2_KAL-298', 'catalog.rajasthan_history_ancient_history_kalibangan', 'ईंटों की नालियों के अतिरिक्त कालीबंगा में जल-निकासी के कौन-से साधन मिले?', 'लकड़ी को खोखला करके बनाई गई नालियाँ और टेराकोटा पाइप भी मिले।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-298 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4d4bcef4597eb3b057069784d52c5f1e783f9481df2d1b41809d05a813e0a575', NULL),
  ('ch2_KAL-299', 'catalog.rajasthan_history_ancient_history_kalibangan', 'ASI के भाग-I की “संरचनाओं की सामान्य विशेषताएँ” शीर्षक वाली सामग्री में ईंटों के कौन-से दो सामान्य आकार दर्ज हैं?', '30 × 15 × 7.5 सेमी तथा 40 × 20 × 10 सेमी।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-299 — S22 — printed p. 130; इसे KAL-029 के अलग Early-Harappan Gazetteer संदर्भ के साथ मिलाकर एक ही मान न मानें — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0e42f74e4672cc1225c94264564b1ca6001ade96fb97588bb1084d423eff96e4', NULL),
  ('ch2_KAL-300', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की क्रमिक सड़क-परतों को मजबूत बनाने के लिए किन सामग्रियों का उपयोग दर्ज है?', 'बजरी, बर्तन-खंड और कोयले आदि का उपयोग किया जाता था।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-300 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b263804c0a998c1c697c8001688692902862ce0523bae1e857795645b3966481', NULL),
  ('ch2_KAL-301', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की ईंटों को जोड़ने में प्रयुक्त गारे/बंधन सामग्री का रंग कैसा बताया गया है?', 'सामान्यतः धूसर या हरा; जहाँ जलभराव हुआ, वहाँ बंधन सामग्री हरी हो गई।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-301 — S22 — “General Features of Structures”, printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '837a37405369f309b5562a7447952d7331cacf711c2bf2b9a62a712f97b9633a', NULL),
  ('ch2_KAL-302', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की सड़कों में अलग-अलग निर्माण और पुनर्निर्माण चरणों का संकेत किससे मिलता है?', 'सड़क से सटी दीवारों/निर्माणों में दिखने वाले बदलावों और लगातार बढ़े हुए सड़क-स्तरों से।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-302 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6395bd00371421dee13af70ce7f8ecf26f9e75bbe8d47bf60fe4e080b2f88a5f', NULL),
  ('ch2_KAL-303', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के घरों के फर्श में कभी-कभी किस प्रकार की सजावटी टाइलें लगाई जाती थीं?', 'नक्काशीदार (incised) सजावटी टाइलें।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-303 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1541a7f4ee72079a7987b113bc212d25464786b6e7f9d74bcb04a29675af40d1', NULL),
  ('ch2_KAL-304', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के घरों में सड़क की ओर बनी दीवार पर स्थित दरवाज़े सामान्यतः कहाँ खुलते थे?', 'घर के आँगन में प्रवेश के लिए।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-304 — S22 — printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '741e139cb6af2e93bffe4faac7688e16b46e6303fb406a97def4b32029b1697d', NULL),
  ('ch2_KAL-305', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की ईंटों की गुणवत्ता और ईंट-चिनाई के कौशल के बारे में ASI रिपोर्ट क्या बताती है?', 'ईंटों के आकार और परिष्करण में एकरूपता थी तथा ईंटें लगाने की कला विकसित थी।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-305 — S22 — “General Features of Structures”, printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6e05f2735adc8c4ac616aa69eb70bbe9f8bf756a43f61e15edfbc95f303cf50c', NULL),
  ('ch2_KAL-306', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के घरों की छतों के निर्माण के बारे में ASI रिपोर्ट का संभावित अनुमान क्या है?', 'छतें संभवतः लकड़ी की बुनावट और मिट्टी के लेप (timber wattle-and-daub) से बनी सपाट थीं।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-306 — S22 — “General Features of Structures”, printed p. 130 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'f1817db8fc0f305f28386df010d4b388a23316b02516222dff496744624bd43a', NULL),
  ('ch2_KAL-307', 'catalog.rajasthan_history_ancient_history_kalibangan', 'ASI रिपोर्ट के अनुसार कालीबंगा के परिपक्व हड़प्पा कालीन चरण IX की सड़कों पर कितने क्रमिक सड़क-स्तर मिले?', 'चार सड़क-स्तर।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-307 — S22 — “General Features of Structures”, printed p. 131 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a111eed3d9e416d54449804995296df12dc1cc9fc56806eed8311a3c45750f31', NULL),
  ('ch2_KAL-308', 'catalog.rajasthan_history_ancient_history_kalibangan', 'रिपोर्ट के अनुसार कालीबंगा के पहले के चरणों की सड़कें कैसी थीं?', 'पहले के चरणों की सड़कें पक्की/फर्शबंद नहीं थीं।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-308 — S22 — “General Features of Structures”, printed p. 131 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6a67cd28ee0d9d4177651dfe57aaa7b0ba124c0ec2ef26e7be57abb22b2b985d', NULL),
  ('ch2_KAL-309', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की सड़कों के किनारे बने फेंडर-पोस्टों का उद्देश्य क्या था?', 'वाहनों की आवाजाही से घरों की दीवारों को बचाना।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-309 — S22 — “General Features of Structures”, printed p. 131; Fig. 6.46 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '9dccafa13710daf3db2c7ff9a6836cde2a699d3adc3aeb7cbbe7312bf9d4feca', NULL),
  ('ch2_KAL-310', 'catalog.rajasthan_history_ancient_history_kalibangan', 'ASI लेखक ने KLB-2 के असाधारण बड़े घर को किसका संभावित निवास माना?', 'किसी धनी व्यापारी या महत्त्वपूर्ण व्यक्ति का; यह लेखक का अनुमान है, निश्चित पहचान नहीं।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-310 — S22 — “General Features of Structures”, printed p. 131 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e0974a4aab3ddfde680ac3cce4f47b7dbe9b2682f1914c444f5c0c9b7aa4cfce', NULL),
  ('ch2_KAL-311', 'catalog.rajasthan_history_ancient_history_kalibangan', 'ASI रिपोर्ट ने कालीबंगा की सड़कों में विस्तृत जल-निकासी व्यवस्था न मिलने को किस संभावित कारण से जोड़ा?', 'कम वर्षा से; यह रिपोर्ट-लेखक की व्याख्या है, प्रत्यक्ष वर्षामान का प्रमाण नहीं।', 'hi', 'https://asi.nic.in/admin/publications/ePublicationReportsDetails/download/60', 'KAL-311 — S22 — “General Features of Structures”, printed p. 131 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1bd0ad931184127db2b25a0433846daf860f36fb8fd87e7c47b84bdd3dbc1e28', NULL),
  ('ch2_AHB-001', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़-बनास संस्कृति किस पुरातात्त्विक काल की संस्कृति है?', 'ताम्रपाषाण (Chalcolithic) संस्कृति।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-001 — S24 — INFLIBNET, अध्याय 27, §4 “The Ahar-Banas Culture” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '73e385b300b28a480af893d547c8c30fe2a57fd0c199a4f8c7fdf40d43442e14', NULL),
  ('ch2_AHB-002', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़-बनास संस्कृति का मुख्य भौगोलिक क्षेत्र राजस्थान के किस भाग में स्थित था?', 'दक्षिण-पूर्वी राजस्थान के मेवाड़ क्षेत्र में, बनास नदी और उसकी सहायक नदियों के आसपास।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-002 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6fb69c8b32acc72472ecd52290d526ceea331cd678bb6f839b8f5d4248fe8ce8', NULL),
  ('ch2_AHB-003', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'INFLIBNET के अध्याय के अनुसार आहड़-बनास संस्कृति का विस्तार किन जिलों में बताया गया है?', 'बांसवाड़ा, उदयपुर, चित्तौड़गढ़, भीलवाड़ा, बूंदी और अजमेर जिलों में।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-003 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3f81050a850bbe02bac9a6942b796d5ff1d746f56b24754d6b055446ab648149', NULL),
  ('ch2_AHB-004', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ स्थल उदयपुर में किस नदी के किस किनारे पर स्थित बताया गया है?', 'आहड़ नदी के बाएँ किनारे पर, उदयपुर रेलवे स्टेशन के निकट।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-004 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 20 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'cba4989ddc93050443f6b86b1553853214c54bd3bda6987731016b2b75234313', NULL),
  ('ch2_AHB-005', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ स्थल को पहली बार प्रकाश में लाने का श्रेय किसे और किस अवधि को दिया गया है?', 'आर. सी. अग्रवाल को, 1954–55 में।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-005 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 20 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3983cef20329af0b5bb91dfb8e1f300c45fc43cc338d6bc1a046d370f2f210a1', NULL),
  ('ch2_AHB-006', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ के प्राचीन टीले का नाम क्या बताया गया है?', 'ताम्रवती (Tambamati), जिसका अर्थ रिपोर्ट में “ताँबे का नगर” बताया गया है।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-006 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 20 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '79015b1cfbf33bbb80bfa6258b836b7ab80349660439f11a9c51095b1d7822e2', NULL),
  ('ch2_AHB-007', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़-बनास संस्कृति की सबसे विशिष्ट मृद्भांड परंपरा कौन-सी मानी गई है?', 'सफेद रंग से बाहर की ओर चित्रित काला-लाल मृद्भांड (Black-and-Red Ware)।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-007 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 20 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '10e16afdff6dd7de5cb39ab78cce84362e807690822b3ca940abae0beb826082', NULL),
  ('ch2_AHB-008', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ के विशिष्ट काला-लाल मृद्भांडों पर किस प्रकार के चित्रांकन-मोटिफ मिलते हैं?', 'समानांतर या तिरछी रेखाएँ, वृत्त और सर्पिल आकृतियाँ।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-008 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 20 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '92fabae8fa72a2c0e67cc529206f63190145ae269c1d1053374e75a87894a5c3', NULL),
  ('ch2_AHB-009', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ के कटोरों की गर्दन पर कौन-सी विशिष्ट सजावटी विशेषता बताई गई है?', 'गर्दन पर खींची गई पतली उत्कीर्ण रेखाएँ।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-009 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 20 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'd3ffa345a69659c7e05117fe813b788823d5fa56893a6e409ea329e39cbee675', NULL),
  ('ch2_AHB-010', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ के विशिष्ट काला-लाल मृद्भांडों के सामान्य पात्र-रूप कौन-से बताए गए हैं?', 'कटोरे और थालियाँ।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-010 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 20 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '941dac29e7226929f5270970f5dc32368993424b5f8a07c33d8045135c88365a', NULL),
  ('ch2_AHB-011', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़ में काला-लाल मृद्भांड के अतिरिक्त किस प्रकार का महीन, चमकाया हुआ चाक-निर्मित मृद्भांड भी मिलता है?', 'लाल-स्लिप वाला मृद्भांड, जिसकी स्लिप का रंग टैन, नारंगी से चॉकलेटी तक बताया गया है।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-011 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 20 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'adc619e48d8c17a1d48cde16daa5a950ad32a5f7328213d2b137525f18a033b7', NULL),
  ('ch2_AHB-012', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'INFLIBNET के अनुसार आहड़ के प्रकार-स्थल के निकट कौन-से प्रमुख आहड़-बनास स्थल सूचीबद्ध हैं?', 'बालाथल, गिलूंड और ओजियाना।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-012 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'bac9ee42666eb4e91bd84bb11cecc38ff356c4f7df61827d68c849228fc0f718', NULL),
  ('ch2_AHB-013', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'INFLIBNET के अनुसार आहड़-बनास संस्कृति का सबसे बड़ा ज्ञात स्थल कौन-सा है?', 'गिलूंड; वहाँ लौहयुगीन साक्ष्य भी बताए गए हैं।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-013 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b1b397b5f05878174df0b2108a2fc6c6c43424e07cf587ab6aa210bc1b61f321', NULL),
  ('ch2_AHB-014', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'ओजियाना स्थल राजस्थान के किस जिले में स्थित है और वहाँ किस संस्कृति का अनुक्रम दर्ज है?', 'भीलवाड़ा जिले में; वहाँ आहड़ संस्कृति का लगभग 7.5 मीटर का अनुक्रम दर्ज है।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-014 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '804b30bc7f85ad590648d827a64c39dccff3ff2264b34254a9715cdf87fa664d', NULL),
  ('ch2_AHB-015', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'बालाथल में उत्खनन किन वर्षों के बीच कई seasons में किया गया?', '1994 से 2000 के बीच।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-015 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a16ec34318fbbed271f91aee9f70de215051bb8e2a123ffda3cb56d6969e253d', NULL),
  ('ch2_AHB-016', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'बालाथल के 30 रेडियोकार्बन तिथिक्रमों के आधार पर आहड़-बनास संस्कृति की कौन-सी calibrated समय-सीमा दी गई है?', 'लगभग 3700–1830 ईसा पूर्व; यह बालाथल के तिथिक्रम पर आधारित सीमा है।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-016 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'cb5ce206163c4c66fa9140463fe8fa7212428a85015a996447853d81500e5d43', NULL),
  ('ch2_AHB-017', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़-बनास संस्कृति की अर्थव्यवस्था के प्रमुख आधार क्या थे?', 'कृषि, पशुपालन और स्थानीय स्तर पर शिकार।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-017 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2566e5490434764b7e0a8aa56a1ce5fa75b5a1f9d7731f951feb140e0ded6d5a', NULL),
  ('ch2_AHB-018', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'INFLIBNET में आहड़-बनास मृद्भांडों का नवीन वर्गीकरण कितने व्यापक समूहों में दिया गया है?', 'चार—लाल मृद्भांड, धूसर/काला मृद्भांड, काला-लाल मृद्भांड और बफ मृद्भांड।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-018 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ec24a99e907884f73ce4ca96632db7bfbf87f679b66cb482d58d43a7589214c1', NULL),
  ('ch2_AHB-019', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़-बनास स्थलों के घरों के सामान्य आकार और निर्माण-सामग्री कैसी बताई गई है?', 'एक-कक्षीय से बहु-कक्षीय, आयताकार, चौकोर या गोलाकार घर; पत्थर, कच्ची ईंट और मिट्टी से निर्मित।', 'hi', 'https://ebooks.inflibnet.ac.in/icp02/chapter/152/', 'AHB-019 — S24 — INFLIBNET, अध्याय 27, §4 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'dff5c4d3b9949ab11e7dd7f941603539c20d04f74d48fc3c04e643ece2fea1dc', NULL),
  ('ch2_AHB-020', 'catalog.rajasthan_history_ancient_history_ahar_banas_culture', 'आहड़-बनास संस्कृति की तिथि के बारे में एक ही निश्चित सीमा देने में सावधानी क्यों जरूरी है?', 'अलग-अलग शोधकर्ताओं ने अलग समय-सीमाएँ प्रस्तावित की हैं; इसलिए हर काल-सीमा को संबंधित विद्वान/स्रोत के नाम से बताना चाहिए।', 'hi', 'https://ignca.gov.in/Asi_data/74144.pdf', 'AHB-020 — S23 — B.R. Meena, “Recent Exploration…”, Puratattva 16, printed p. 21; रिपोर्ट में D.P. Agarwal, Ahar excavator और Allchins के अलग प्रस्ताव दिए हैं — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e4e32e687ca510fdb10b21d8a7ab6bd0d32ad6a5443c1e9744a17d93e694897f', NULL),
  ('ch2_GJ-001', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI की 1981–82 की रिपोर्ट में गणेश्वर का स्थान किस जिले और किन निर्देशांकों पर दर्ज है?', 'सीकर जिला; लगभग 27°40′ उत्तरी अक्षांश और 75°51′30″ पूर्वी देशांतर।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-001 — S25 — *Indian Archaeology 1981–82 — A Review*, printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '9280dd5f1c1ad06677c7cd9c23640d988758ce818859a22c6fd5171cea4d41f5', NULL),
  ('ch2_GJ-002', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI रिपोर्ट के अनुसार गणेश्वर किस नदी के उद्गम के पास स्थित है?', 'कांटली नदी के उद्गम के पास; रिपोर्ट में कांटली के उत्तर में सोथी-भाद्रा के निकट प्राचीन दृशद्वती से मिलने का उल्लेख है।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-002 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6f73382ddcfd009a9ac5a0d8e47b55c79c85602d2134b011f63195766f179f4e', NULL),
  ('ch2_GJ-003', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर के उत्खनन में किस काल की संस्कृति और कितने संरचनात्मक चरण दर्ज किए गए?', 'ताम्रयुगीन संस्कृति की एक सांस्कृतिक परत, जिसमें तीन संरचनात्मक चरण थे।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-003 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6b5d99668cdbb628f85c4c928e58b1e0ca1b1cb684d74aaddde12d6b880f5174', NULL),
  ('ch2_GJ-004', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI रिपोर्ट के अनुसार गणेश्वर का कुल आवासीय सांस्कृतिक जमाव लगभग कितना मोटा था?', 'लगभग 3.65 मीटर।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-004 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3ee1f32e7078cd3910ef1ffa6b436f70e4083f4ddfc99aad74c0d3e15bf0d9b3', NULL),
  ('ch2_GJ-005', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर के सांस्कृतिक जमाव में किन तीन प्रमुख प्रकार की पुरावस्तुओं के प्रमाण मिले?', 'ताँबे की वस्तुएँ, लघु पाषाण उपकरण (microliths) और मृद्भांड।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-005 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '73d650e47b33125c82f22f5def5848a84baa9bd42da93ee68e944b49a3fd78be', NULL),
  ('ch2_GJ-006', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर के ताँबे के पुरावशेषों में हथियार, औज़ार और आभूषण के कौन-से उदाहरण मिले?', 'तीराग्र व भालाग्र; छेनी व मछली पकड़ने के काँटे; छल्ले, केश-पिन और चूड़ियाँ।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-006 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '334336fa1c165c696a6a2a930cf1c37f11abbe6ee5ae4f3904daee8a3792b695', NULL),
  ('ch2_GJ-007', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI रिपोर्ट में गणेश्वर से पहले प्राप्त ताँबे की सपाट कुल्हाड़ियों और काँटेदार तीराग्रों की संख्या कितनी दी गई है?', '58 बिना socket वाली सपाट ताँबे की कुल्हाड़ियाँ और 2 काँटेदार तीराग्र।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-007 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c71bb1e0bcb8e1c7c076dab0c3e3d260108b79ec160799e62e63ddf113aa46df', NULL),
  ('ch2_GJ-008', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर में स्थानीय ताँबा-उद्योग के लिए अयस्क मिलने की दूरी और प्रमुख अयस्क किस रूप में बताए गए हैं?', 'रिपोर्ट के अनुसार 20–30 किमी के दायरे में; व्यापक chalcopyrite (ताम्र-पाइराइट) निक्षेप संभावित स्रोत थे। यह रिपोर्ट की व्याख्या है।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-008 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '61e26c9964c467c65466b356d1ad75ac8301fc02430d49f6c8df32fca7ffe234', NULL),
  ('ch2_GJ-009', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI रिपोर्ट ने गणेश्वर में बाढ़ से बचाव के लिए कौन-सा निर्माण-उपाय दर्ज किया?', 'बाढ़ से क्षति के बाद लोगों ने लगातार तीन चरणों में तीन पत्थर के चबूतरे/प्लेटफॉर्म बनाए।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-009 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ffeea4e71f743f159bd719a1100cafa21022b4c673c811980d156ad0304ae60c', NULL),
  ('ch2_GJ-010', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर के ज्यामितीय microlith उद्योग में प्रमुख उपकरण-प्रकार कौन-से बताए गए हैं?', 'blunted-back और obliquely-blunted blades, lunates, triangles, trapezes और points।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-010 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'bc88e0b22903716c0ca902c5bdc1ca4af3dc44b3904d3302800e213d0ed9f8be', NULL),
  ('ch2_GJ-011', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर के microlith बनाने में किन प्रमुख पत्थरों का उपयोग किया गया?', 'क्वार्ट्ज, चर्ट, गार्नेट, कैल्सेडोनी और कभी-कभी जैस्पर।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-011 — S25 — printed p. 61 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '432e5871504ec55abfe982ed3cc3f18eaca041de415da23e4f2a8ca9dfb8b0ea', NULL),
  ('ch2_GJ-012', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI रिपोर्ट में गणेश्वर-जोधपुरा OCP मृद्भांडों के पात्र-रूप कितने समूहों में बाँटे गए हैं?', 'छह—भंडारण-पात्र, फूलदान, बेसिन, कटोरे, ढक्कन और लघु पात्र।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-012 — S25 — printed pp. 61–62 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6765d5882ff2a30921ed1094c6f6b3df6d53b3305d35ed33814e86d8c7364626', NULL),
  ('ch2_GJ-013', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर के OCP फूलदानों की विशिष्ट पकड़/हैंडल व्यवस्था क्या बताई गई है?', 'ऊर्ध्वाधर हैंडल, जो पात्र के rim और shoulder के बीच जोड़े गए थे।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-013 — S25 — printed p. 62 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '5bb69e3fb1afe49f96e359b4a6bb2c0b525dd0e566c4d14c279c1c9e1995436c', NULL),
  ('ch2_GJ-014', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर के चित्रित OCP मृद्भांडों पर चित्रांकन सामान्यतः किन भागों पर मिलता था?', 'मुख्यतः rim, neck और shoulder पर; कुछ पात्रों में चित्र पेट के नीचे तक भी जाते थे।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-014 — S25 — printed p. 62 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8061be9ba0c3de197d51835e8a1adc510ed6532a276d33d43ce024c5dae6c181', NULL),
  ('ch2_GJ-015', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'गणेश्वर के चित्रित OCP मृद्भांडों पर कौन-से प्रमुख अलंकरण-मोटिफ दर्ज हैं?', 'मोटी गर्दन-पट्टी, कंधे पर पतली समानांतर रेखाएँ, लहरदार रेखाओं के बीच क्षैतिज पट्टी, तिरछी रेखाएँ और crescentic-comb pattern।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-015 — S25 — printed p. 62 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b373adb4ea3aec0f7464c89aaf98cb8651b7abfe3c76ca7b64c35751ca8fb5b4', NULL),
  ('ch2_GJ-016', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI रिपोर्ट में गणेश्वर के मृद्भांडों पर मिले graffiti के कौन-से प्रतीक उदाहरण दिए गए हैं?', 'त्रिशूल, hatched quadrangle (रेखांकित चतुर्भुज) और सीढ़ी-जैसा चिह्न।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-016 — S25 — printed p. 62 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0959621b70bac4cb8e153726f97d10dfe14658bf40ef136a513ace8525c6675b', NULL),
  ('ch2_GJ-017', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI रिपोर्ट में गणेश्वर के OCP और जोधपुरा के मृद्भांडों के बीच क्या संबंध बताया गया है?', 'दोनों की ceramic सामग्री में निकट समानता बताई गई है।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-017 — S25 — printed p. 62 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'f08479f761879cfb5cb8a0328f7fcc64ce01080a75ee2d12257637441abcf6f1', NULL),
  ('ch2_GJ-018', 'catalog.rajasthan_history_ancient_history_ganeshwar_jodhpura_culture', 'ASI की 1981–82 रिपोर्ट में गणेश्वर के OCP की रेडियोकार्बन-आधारित तिथि-सीमा क्या दी गई है?', 'लगभग 2500–2200 ईसा पूर्व; यह उसी रिपोर्ट में उद्धृत C-14 निर्धारण है।', 'hi', 'https://nmma.nic.in/nmma/NAS1/nmma_doc/IAR/Indian%20Archaeology%201981-82%20A%20Review.pdf', 'GJ-018 — S25 — printed p. 62 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4e7ab1940e8302cad732ebeee6f003680ddab45aecfb69874c7379f0f318073c', NULL),
  ('ch2_BRT-001', 'catalog.rajasthan_history_ancient_history_bairat', 'ASI की Jaipur Circle सूची में बैराठ/विराटनगर किस जिले और तहसील में दर्ज है?', 'जयपुर जिले की विराटनगर तहसील में।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-001 — S26 — *Inventory of Monuments and Sites of National Importance*, Vol. II, Part 1, entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '1722c9155522d9dbb21cab176388190d039ccce42da37f22b58fa87a72b0acaf', NULL),
  ('ch2_BRT-002', 'catalog.rajasthan_history_ancient_history_bairat', 'ASI सूची में बैराठ/विराटनगर के लगभग निर्देशांक क्या दिए गए हैं?', '27°25′ उत्तरी अक्षांश और 76°10′ पूर्वी देशांतर।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-002 — S26 — entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '43074a2ad2cc8cda4d332284132ad0cf6063debf76019697acd988eab68d4b5d', NULL),
  ('ch2_BRT-003', 'catalog.rajasthan_history_ancient_history_bairat', 'ASI सूची बैराठ अथवा प्राचीन विराटनगर को किस जनपद की राजधानी बताती है?', 'मत्स्यदेश की राजधानी।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-003 — S26 — entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '068d9394f1f4462c7a9c3bc94fb0a0c946c2bcd65e9b6f9dc33603ab6273d888', NULL),
  ('ch2_BRT-004', 'catalog.rajasthan_history_ancient_history_bairat', 'ASI के अनुसार बैराठ किस दो प्रकार के प्रमुख प्राचीन साक्ष्यों के लिए प्रसिद्ध है?', 'दो अशोक-कालीन अभिलेखों और प्राचीन बौद्ध अवशेषों के लिए।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-004 — S26 — entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2ac146331e67b19307b3aadfc256cdcf0585ef2e3642a9a2bed2d35497843bd0', NULL),
  ('ch2_BRT-005', 'catalog.rajasthan_history_ancient_history_bairat', 'बैराठ के बिजक-की-पहाड़ी पर उत्खनन से किस काल का कौन-सा प्रमुख धार्मिक स्थापत्य मिला?', 'मौर्यकालीन वृत्ताकार स्तूप-मंदिर (circular stupa-shrine)।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-005 — S26 — entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a9a5a9e045e87c8e65477b01c8837a09665c2914d0bd37db0a457353aaac2f70', NULL),
  ('ch2_BRT-006', 'catalog.rajasthan_history_ancient_history_bairat', 'बैराठ के वृत्ताकार स्तूप-मंदिर में ईंट-निर्माण के साथ कितने अष्टकोणीय लकड़ी के स्तंभ बताए गए हैं?', '26 अष्टकोणीय लकड़ी के स्तंभ, जिनके बीच ईंट-चिनाई थी।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-006 — S26 — entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '004db2802f62bfaaf9b65cc68c045a2e1502b827ad0cf454b1ce5a30fba20edd', NULL),
  ('ch2_BRT-007', 'catalog.rajasthan_history_ancient_history_bairat', 'बैराठ के स्तूप-मंदिर से पहले मिले मठीय अवशेषों की योजना कैसी थी?', 'खुले वर्गाकार आँगन के चारों ओर दोहरी पंक्ति में कक्ष बने थे।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-007 — S26 — entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '5cc399ec5f9328f49f9cc15a56a5bd4ef328f3809cd52826c112dcece256a908', NULL),
  ('ch2_BRT-008', 'catalog.rajasthan_history_ancient_history_bairat', 'बैराठ के दो अशोक-कालीन अभिलेखों के नाम PMML के अध्ययन में कौन-से दिए गए हैं?', 'Calcutta-Bairat Rock Edict और Minor Rock Edict I।', 'hi', 'https://pmml.nic.in/downloadSeries/342', 'BRT-008 — S27 — PMML, “Understanding the Ashokan Inscriptions and the Archaeological Landscape of Bairat” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '9e56fed38936f4b0ecd1eda38fe7e68f59001a9b9aaf517bacc1c424f2eb746a', NULL),
  ('ch2_BRT-009', 'catalog.rajasthan_history_ancient_history_bairat', 'बैराठ के उत्खनित स्थल को ASI inventory में किस अधिसूचना से जोड़ा गया है?', 'Act No. LXXI of 1951, दिनांक 28 नवम्बर 1951।', 'hi', 'https://ignca.gov.in/Asi_data/88329.pdf', 'BRT-009 — S26 — entry 107, printed p. 143 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '11ee11de9bbc1a00ba3d378ba20c7e35a7e1dbf4281f20956cc892a9774feab3', NULL),
  ('ch2_MTS-001', 'catalog.rajasthan_history_ancient_history_matsya_janapada', 'राजस्थान बोर्ड की पाठ्यपुस्तक के अनुसार मत्स्य जनपद का उल्लेख किस बौद्ध ग्रंथ की 16 जनपदों की सूची में है?', 'अंगुत्तर निकाय की 16 जनपदों की सूची में।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'MTS-001 — S28 — अध्याय 1, “Janapadas of Rajasthan”, मुद्रित पृ. 7 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '6435f5bcbf53cb3d3cda28033b8d33522c6390173c96cf0cab2058cf08dc8e05', NULL),
  ('ch2_MTS-002', 'catalog.rajasthan_history_ancient_history_matsya_janapada', 'राजस्थान बोर्ड की पाठ्यपुस्तक के अनुसार मत्स्य जनजाति का प्रारंभिक उल्लेख किस वेद में मिलता है?', 'ऋग्वेद में।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'MTS-002 — S28 — “Matsya Janapada”, मुद्रित पृ. 7 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '8beb551e740a2d79e97b05ee0bdcde3fc6668fe6831a9e38bc6f2929abb31c14', NULL),
  ('ch2_MTS-003', 'catalog.rajasthan_history_ancient_history_matsya_janapada', 'ऋग्वेद के अतिरिक्त S28 में मत्स्य जनजाति का उल्लेख किन दो वैदिक ग्रंथों में बताया गया है?', 'शतपथ ब्राह्मण और कौषीतकि उपनिषद में।', 'hi', 'https://rajeduboard.rajasthan.gov.in/books-2019/books-2022/cls10/HistorynCulture.pdf', 'MTS-003 — S28 — “Matsya Janapada”, मुद्रित पृ. 7 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '5bb87b465cfabb1e0a1602dc8572f01290e27c590bee07a857a70ffc4e7da2c1', NULL),
